'use strict';
/* Guide — partie 2 (français) : Ressources narratives, Techniques narratives, Méthodes narratives et Styles narratifs.
   Même format que les autres parties : { n, a, d, u, c, x, t, s }. Norme de France ; les variantes belges, suisses
   et québécoises sont signalées quand elles comptent. Les titres d’œuvres sont en *italique*. */

/* ============ RESSOURCES NARRATIVES ============ */
SUPPORT.push({ key:'recursos', name:'Ressources narratives', kicker:'Ressource',
  intro:'Les dispositifs qui font fonctionner l’intrigue : ce que l’on met dans l’histoire, et dans quel ordre on le révèle, pour créer l’attente, la surprise et le sens. Les figures travaillent la phrase ; ces ressources travaillent l’histoire — le temps, l’information dont dispose le lecteur, les moteurs du conflit et les fonctions des personnages.',
  groups:[
  { name:'Temps et ordre', items:[
    { n:'Analepse', a:'Retour en arrière · flash-back · rétrospection',
      d:'Retour dans le temps : la narration interrompt le présent de l’histoire pour raconter des événements antérieurs. Le terme est celui de Gérard Genette (*Figures III*, 1972), qui l’oppose à la prolepse.',
      u:'Employez-la quand le passé devient nécessaire pour comprendre le présent — de préférence quand le lecteur a déjà envie de savoir. Entrez et sortez par un déclencheur concret (une odeur, un objet, une phrase). Elle peut tenir en une scène entière, un paragraphe ou une simple phrase de souvenir. Le plus-que-parfait sert de sas d’entrée ; revenez vite au passé simple pour que la scène vive.',
      c:'Une analepse dès les premières pages freine le démarrage ; si le passé est plus intéressant que le présent, l’histoire devrait peut-être commencer là. Trop de plus-que-parfaits alourdissent la page.',
      x:['*Thérèse Desqueyroux* (Mauriac) : dans le train qui la ramène chez elle, Thérèse revit tout ce qui l’a conduite au crime.', 'L’*Odyssée* : Ulysse raconte lui-même ses errances aux Phéaciens.', '*Les Hauts de Hurlevent* : presque tout le roman est le récit rétrospectif de Nelly Dean.', '*Le Parrain, 2e partie* : la jeunesse de Vito en parallèle avec le présent de Michael.'],
      t:'Chaque Scène a deux positions : l’ordre narratif (où elle est racontée, sur la ligne blanche du Récit) et l’ordre chronologique (quand elle se passe, sur la ligne de couleur de son Arc narratif). Une analepse est une Scène tardive dans le Récit et reculée dans la chronologie.',
      s:['Prolepse', 'In medias res', 'Récit non linéaire', 'Récit circulaire'] },
    { n:'Prolepse', a:'Anticipation · flash-forward',
      d:'Saut en avant : la narration annonce des événements qui n’arriveront que plus tard.',
      u:'Elle remplace la question « que va-t-il se passer ? » par « comment cela va-t-il arriver ? ». Une phrase suffit (« Ce serait la dernière fois qu’il la verrait »). Prophéties, rêves et présages sont des prolepses internes à l’histoire. Le conditionnel « futur du passé » (« il la reverrait trente ans plus tard ») est son outil naturel en français.',
      c:'Trop anticiper ôte la tension des scènes qui suivent.',
      x:['*Cent ans de solitude* s’ouvre sur le colonel Aureliano Buendía face au peloton d’exécution, bien des années plus tard.', '*Chronique d’une mort annoncée* (García Márquez) : la mort est annoncée dès la première phrase.', 'Chez Proust, le narrateur annonce souvent ce qu’il ne comprendra que des années plus tard.', 'Les prophéties de l’oracle dans *Œdipe roi*.'],
      s:['Analepse', 'Préfiguration', 'Ironie dramatique', 'Temps de la narration'] },
    { n:'In medias res', a:'Commencer au milieu · « au milieu des choses »',
      d:'Ouvrir le récit sur une action déjà engagée, en réservant les antécédents pour plus tard. Le contraire est de commencer *ab ovo*, par l’origine de tout. La formule vient de l’*Art poétique* d’Horace.',
      u:'Ouvrez sur une scène en mouvement qui pose une question, au plus près de l’élément déclencheur. Ne donnez que le contexte indispensable et distribuez le reste ensuite, par analepses ou par le dialogue.',
      c:'Commencer par de l’action pure, sans personnage auquel le lecteur tienne, n’est que du bruit ; et un retour au passé dès le deuxième chapitre peut décevoir.',
      x:['L’*Odyssée* s’ouvre alors qu’Ulysse est loin de chez lui depuis des années ; l’*Iliade*, dans la dixième et dernière année de la guerre.', '*La Métamorphose* (Kafka) : Gregor Samsa se réveille déjà transformé.', '*L’Étranger* (Camus) commence par la mort de la mère, annoncée d’emblée : « Aujourd’hui, maman est morte. »'],
      s:['Analepse', 'Élément déclencheur', 'Entrer tard, sortir tôt', 'Exposition distillée'] },
    { n:'Course contre la montre', a:'Compte à rebours · échéance · *ticking clock*',
      d:'Une limite de temps connue du lecteur, au-delà de laquelle quelque chose d’irréversible se produira.',
      u:'Elle donne de l’urgence à n’importe quel objectif et oblige les personnages à agir — et à se tromper. L’échéance doit être concrète (minuit, le mariage, la marée, l’oxygène) et peut être raccourcie en cours de route pour resserrer la tension.',
      x:['*Le Tour du monde en quatre-vingts jours* (Jules Verne) : le pari de Phileas Fogg, et le jour gagné in extremis.', 'Le minuit de Cendrillon chez Perrault.', '*Le train sifflera trois fois* : le tueur arrive par le train de midi.', '*Chronique d’une mort annoncée* : tout le village connaît l’heure, sauf la victime.'],
      s:['Enjeux', 'Suspense et surprise', 'Rythme narratif'] },
    { n:'Récit circulaire', a:'Structure circulaire · composition en boucle',
      d:'La fin revient au point de départ — le même lieu, la même image, la même phrase ou la même situation —, mais avec un sens transformé par ce qui s’est passé entre-temps.',
      u:'Montrez la même image au début et à la fin : l’écart entre les deux mesure l’arc du personnage. Ou ne changez rien — et le retour devient condamnation.',
      x:['*Le Hobbit* a pour sous-titre *Un aller et retour*.', '*À la recherche du temps perdu* s’achève sur la décision d’écrire le livre que l’on vient de lire.', '*Finnegans Wake* (Joyce) : la dernière phrase se poursuit dans la première.', '*En attendant Godot* (Beckett) : le second acte reprend le premier, et rien n’arrive deux fois.'],
      s:['Récit enchâssé', 'Arc de personnage', 'Dénouement'] }
  ]},
  { name:'Information, suspense et révélation', items:[
    { n:'Préfiguration', a:'Annonce · indice · présage · *foreshadowing*',
      d:'Signe discret qui annonce ce qui viendra : un détail, une réplique, une image, un rêve, un incident mineur qui répète en petit l’incident majeur.',
      u:'L’idéal est qu’elle passe inaperçue à la première lecture et paraisse inévitable à la seconde. Cachez-la au milieu d’une énumération, d’une scène comique ou d’une scène d’action. Écrivez d’abord le dénouement, puis revenez en arrière pour le semer.',
      c:'Trop visible, elle gâche la surprise ; absente, elle rend le dénouement arbitraire.',
      x:['*Madame Bovary* : Emma découvre le bouquet de mariée de la première épouse ; en quittant Tostes, elle jette le sien au feu ; la chanson de l’Aveugle revient jusqu’à son agonie.', '*Roméo et Juliette* : le prologue et les pressentiments des amants.', '*Des souris et des hommes* (Steinbeck) : la mort du vieux chien répète la fin.'],
      t:'Associez une même Note aux deux Scènes — celle qui sème et celle qui récolte — pour ne perdre aucune préfiguration de vue.',
      s:['Semer et récolter', 'Fusil de Tchekhov', 'Prolepse', 'Fausse piste'] },
    { n:'Fusil de Tchekhov', a:'Principe d’économie dramatique',
      d:'Principe d’économie : tout ce qui est mis en relief dans l’histoire doit servir. S’il y a un fusil accroché au mur au premier acte, il doit avoir tiré au dernier.',
      u:'Lisez-le dans les deux sens : coupez ce qui ne servira pas — et présentez à l’avance tout ce qui sera décisif à la fin (l’objet, le savoir-faire, la faiblesse).',
      c:'Cela ne veut pas dire que chaque détail doit être un indice : un décor a besoin de texture. Le principe s’applique à ce que le texte souligne.',
      x:['Dans *Oncle Vania*, de Tchekhov lui-même, le pistolet tire — et manque sa cible.', '*Madame Bovary* : le « capharnaüm » du pharmacien et le bocal d’arsenic, montrés bien avant qu’Emma n’y vienne.', 'Le Retourneur de Temps et tant d’objets de *Harry Potter* : présentés comme des curiosités, décisifs plus tard.'],
      s:['Semer et récolter', 'Préfiguration', 'Deus ex machina'] },
    { n:'Semer et récolter', a:'Préparation et paiement · *setup* et *payoff*',
      d:'Une paire de moments : quelque chose est établi tôt (un objet, une phrase, une règle, une promesse) et revient plus tard avec des conséquences. C’est le mécanisme général dont la préfiguration et le fusil de Tchekhov sont des cas particuliers.',
      u:'Semez trois fois ce qui est essentiel, dans des contextes différents ; récoltez quand le lecteur l’a presque oublié. Toute promesse faite au lecteur (un mystère, une menace, un baiser différé) est une dette à payer.',
      c:'Une récolte sans semis sent la tricherie ; un semis sans récolte, le fil qui pend.',
      x:['*Retour vers le futur* : le tract sur la foudre tombée sur l’horloge.', 'La règle « ne jamais croiser les effluves » dans *SOS Fantômes*.', '*Le Comte de Monte-Cristo* : chaque mot de l’abbé Faria sur le trésor resurgit des centaines de pages plus loin.'],
      t:'Associez la même Référence ou la même Note aux Scènes où l’on sème et à celles où l’on récolte.',
      s:['Fusil de Tchekhov', 'Préfiguration', 'Révision par passes', 'Planifier à partir de la fin'] },
    { n:'Fausse piste', a:'Leurre · *red herring* (hareng rouge)',
      d:'Élément qui détourne volontairement l’attention et les soupçons du lecteur dans une mauvaise direction.',
      u:'Elle doit être plausible et recevoir sa propre explication à la fin (le suspect cachait autre chose). La meilleure dissimule la vraie piste, présentée au même moment et avec moins d’éclat.',
      c:'Jamais expliquée, c’est un fil qui pend ; s’il n’y a que de fausses pistes, le lecteur se sent floué.',
      x:['Rogue (Snape) dans *Harry Potter à l’école des sorciers*.', '*Le Mystère de la chambre jaune* (Gaston Leroux) : tout accuse Robert Darzac.', '*Le Chien des Baskerville* (Conan Doyle) : le forçat évadé dans la lande.'],
      s:['Préfiguration', 'Coup de théâtre', 'Roman policier'] },
    { n:'Suspense et surprise', a:'La bombe sous la table (Hitchcock)',
      d:'Surprise : le lecteur ne sait pas ce qui vient et il est pris de court — quinze secondes de choc. Suspense : le lecteur sait qu’une bombe est cachée sous la table et les personnages l’ignorent — quinze minutes d’angoisse. Hitchcock développe l’exemple dans ses entretiens avec François Truffaut (*Hitchcock/Truffaut*, 1966).',
      u:'Pour créer du suspense, donnez l’information au lecteur au lieu de la cacher, rendez les deux issues possibles et retardez le dénouement. Le suspense exige que le lecteur tienne à celui qui est en danger.',
      c:'Les surprises en série fatiguent ; le suspense sans résolution agace.',
      x:['*Psychose* : la surprise de la douche ; puis le suspense chaque fois que quelqu’un s’approche de la maison.', '*Les Dents de la mer* : le spectateur voit l’aileron avant les baigneurs.', '*Le Salaire de la peur* (Georges Arnaud) : des camions de nitroglycérine sur une piste défoncée — chaque cahot est une bombe sous la table.'],
      s:['Ironie dramatique', 'Course contre la montre', 'Question dramatique', 'Accroche et cliffhanger'] },
    { n:'Ironie dramatique', a:'Ironie tragique',
      d:'Le lecteur sait quelque chose qu’un ou plusieurs personnages ignorent. Chaque réplique et chaque geste prennent alors un double sens.',
      u:'Source de tension (le danger que nous seuls voyons), de comique (le quiproquo) et de tragique (l’erreur que nous seuls comprenons). Elle fonctionne très bien avec plusieurs points de vue : ce que sait un Personnage POV, le suivant l’ignore.',
      x:['*Œdipe roi* (Sophocle) : Œdipe cherche l’assassin qu’il est lui-même.', '*Tartuffe* (Molière) : Orgon, caché sous la table, entend l’hypocrite courtiser sa femme.', '*Roméo et Juliette* : nous savons que Juliette n’est qu’endormie.'],
      t:'Avec plusieurs Arcs narratifs et Personnages POV, le Récit montre ce que chaque fil a déjà révélé à chaque moment de l’ordre narratif.',
      s:['Suspense et surprise', 'Péripétie et reconnaissance', 'Ironie', 'Personnage POV'] },
    { n:'Question dramatique', a:'Question centrale',
      d:'La question que l’histoire pose au début et à laquelle elle ne répond qu’au climax : le héros réussira-t-il ? Qui a tué ? Finiront-ils ensemble ? Chaque scène pose aussi des questions plus petites.',
      u:'Formulez la question centrale en une phrase et vérifiez que le climax y répond. Pour tenir le lecteur, ouvrez une question nouvelle avant de refermer la précédente.',
      x:['« Qui a tué Roger Ackroyd ? »', '« Ulysse rentrera-t-il à Ithaque — et que trouvera-t-il ? »', '« Edmond Dantès obtiendra-t-il vengeance, et à quel prix ? »'],
      s:['Accroche et cliffhanger', 'Climax', 'Prémisse et pitch'] },
    { n:'Accroche et cliffhanger', a:'Incipit accrocheur · fin de chapitre à suspense',
      d:'Élément qui saisit le lecteur et l’oblige à continuer. À l’ouverture : une phrase, une voix ou une situation intrigante. En fin de chapitre (le *cliffhanger*, littéralement « suspendu à la falaise ») : une interruption au moment de plus forte tension, une révélation ou une nouvelle question.',
      u:'Coupez le chapitre avant la réponse, pas après. Variez les types (danger, révélation, décision, arrivée de quelqu’un). Avec plusieurs fils, changer de fil après une accroche en double l’effet.',
      c:'Si tous les chapitres se terminent par un évanouissement, le procédé se voit ; et une accroche résolue par une banalité est une tromperie.',
      x:['Shéhérazade dans *Les Mille et Une Nuits* : interrompre l’histoire à l’aube pour survivre un jour de plus.', 'Les romans-feuilletons — Eugène Sue, Dumas, Ponson du Terrail — vivaient de « la suite au prochain numéro ».', '*Da Vinci Code* (Dan Brown) : des chapitres courts, presque tous terminés par une accroche.'],
      s:['Chapitres courts et cliffhangers', 'Suspense et surprise', 'Montage alterné', 'Roman-feuilleton', 'Incipit'] },
    { n:'Coup de théâtre', a:'Rebondissement · retournement de situation · *twist*',
      d:'Changement brusque et inattendu du cours de l’histoire, ou de la façon dont nous la comprenons.',
      u:'Le bon coup de théâtre est à la fois surprenant et inévitable : il saisit sur le moment et, rétrospectivement, tout était là. Il oblige à réinterpréter ce qu’on a lu et fait monter les enjeux. Construisez-le à partir de la fin et semez les indices à la vue de tous.',
      c:'Le retournement qui contredit ce qui a été montré, ou qui annule ce que le lecteur a vécu (« ce n’était qu’un rêve »), est ressenti comme une trahison.',
      x:['*Le Meurtre de Roger Ackroyd* (Agatha Christie).', '*Celle qui n’était plus* (Boileau-Narcejac), porté à l’écran par Clouzot sous le titre *Les Diaboliques*.', '*Les Apparences* (*Gone Girl*, Gillian Flynn) : le basculement au milieu du livre.', '*L’Empire contre-attaque* : « Je suis ton père. »'],
      s:['Péripétie et reconnaissance', 'Préfiguration', 'Fausse piste', 'Point médian', 'Narrateur non fiable'] },
    { n:'Péripétie et reconnaissance', a:'Anagnorisis · retournement et reconnaissance (Aristote)',
      d:'La péripétie est le renversement soudain de la situation, du bonheur au malheur ou l’inverse. La reconnaissance (anagnorisis) est le passage de l’ignorance à la connaissance : un personnage découvre une identité ou une vérité. Selon la *Poétique*, l’effet est le plus fort quand les deux coïncident. (Dans l’usage courant, « péripétie » désigne aussi n’importe quel incident d’un récit.)',
      u:'Faites de la révélation un acte qui change tout : la reconnaissance doit forcer une décision. Elle peut porter sur un autre (qui il est) ou sur soi (qui je suis, ce que j’ai fait).',
      x:['*Œdipe roi* : le messager venu rassurer Œdipe lui révèle son origine — et le détruit.', 'Le retour d’Ulysse, reconnu à sa cicatrice par la nourrice Euryclée.', '*L’Avare* (Molière) : la reconnaissance finale qui révèle qu’Anselme est le père de Valère et de Mariane.', '*Cyrano de Bergerac* : Roxane comprend enfin, à la lecture de la dernière lettre, qui l’aimait.'],
      s:['Coup de théâtre', 'Ironie dramatique', 'Climax', 'Faute tragique'] }
  ]},
  { name:'Moteurs de l’intrigue', items:[
    { n:'Élément déclencheur', a:'Élément perturbateur · incident déclencheur · catalyseur',
      d:'L’événement qui rompt l’équilibre initial et met l’histoire en marche : sans lui, la vie du personnage continuerait comme avant. Dans le schéma quinaire enseigné à l’école, c’est l’« élément perturbateur ».',
      u:'Il doit arriver tôt, en scène (pas en résumé), toucher le protagoniste et poser la question dramatique. Ce peut être une occasion, une perte, une rencontre, une lettre, un cadavre.',
      x:['L’arrivée de Bingley dans le voisinage, dans *Orgueil et Préjugés*.', '*Le Rouge et le Noir* : M. de Rênal engage Julien Sorel comme précepteur.', '*Le Grand Meaulnes* : l’arrivée d’Augustin Meaulnes à l’école de Sainte-Agathe.', 'La lettre de Poudlard.'],
      s:['Structure en trois actes', 'Schéma quinaire', 'Question dramatique', 'Point de non-retour', 'In medias res'] },
    { n:'Enjeux', a:'Ce qui est en jeu · *stakes*',
      d:'Ce que le personnage gagne s’il réussit et, surtout, ce qu’il perd s’il échoue.',
      u:'Rendez-les clairs, personnels et croissants. Les enjeux extérieurs (la vie, le royaume, l’emploi) pèsent davantage quand ils sont liés aux enjeux intérieurs (l’identité, l’amour, la culpabilité). Montrez tôt ce qui peut être perdu, pour que le lecteur s’y attache.',
      c:'« La fin du monde » est un enjeu abstrait ; la mort d’une personne que nous connaissons pèse plus que celle d’une planète.',
      x:['*Hunger Games* : la vie même — et celle de la petite sœur.', '*Le Seigneur des anneaux* : la Terre du Milieu, mais aussi la Comté et l’âme de Frodon.', '*Les Vestiges du jour* (Ishiguro) : une seule vie gâchée — et c’est assez.'],
      s:['Course contre la montre', 'Dilemme', 'Obstacles et complications'] },
    { n:'Obstacles et complications', a:'Conflit · escalade',
      d:'Tout ce qui s’oppose au désir du personnage : un antagoniste, le milieu, la société, la nature, le destin — ou lui-même. La complication est l’obstacle qui, non content de bloquer, aggrave ou modifie la situation.',
      u:'Sans opposition, pas d’histoire. Faites croître les obstacles en difficulté et variez leur nature (extérieure, relationnelle, intérieure). Le meilleur obstacle naît du plan même du personnage ou du désir légitime d’un autre.',
      x:['Types de conflit : personnage contre personnage (*Les Misérables* : Valjean et Javert), contre la société (*1984*), contre la nature (*Le Vieil Homme et la Mer*), contre lui-même (*Crime et Châtiment*), contre le destin (*Œdipe roi*).'],
      s:['Tentatives et échecs', 'Antagoniste', 'Dilemme', 'Courbe de Fichte', 'Schéma actanciel'] },
    { n:'Dilemme', a:'Choix impossible · dilemme cornélien',
      d:'Choix entre deux options incompatibles, toutes deux coûteuses : deux biens qui s’excluent ou deux maux inévitables. Le français a un adjectif pour le plus célèbre : le dilemme « cornélien », entre l’amour et le devoir.',
      u:'C’est dans le choix sous pression que le personnage se révèle. Placez le dilemme au climax, et faites que la décision coûte quelque chose que nous connaissons.',
      c:'Si l’une des options est clairement la meilleure, ce n’est pas un dilemme — seulement un obstacle.',
      x:['*Le Cid* (Corneille) : Rodrigue doit venger son père en tuant celui de Chimène, qu’il aime.', 'Antigone, chez Sophocle comme chez Anouilh : obéir à la loi de la cité ou ensevelir son frère.', '*Le Choix de Sophie* (William Styron).', 'Frodon au mont du Destin.'],
      s:['Enjeux', 'Climax', 'Arc de personnage', 'Classicisme'] },
    { n:'MacGuffin', a:'Terme popularisé par Hitchcock',
      d:'L’objet ou l’objectif que tous les personnages poursuivent et qui met l’intrigue en mouvement, mais dont la nature exacte importe peu au public. Hitchcock en donne la définition la plus connue dans ses entretiens avec Truffaut.',
      u:'Il donne aux personnages une raison de se croiser et de s’affronter ; l’intérêt est dans ce qu’ils font pour l’obtenir. On gagne beaucoup à lui donner en plus une valeur symbolique ou affective.',
      x:['Les ferrets de la reine dans *Les Trois Mousquetaires* (Dumas).', 'La statuette du *Faucon maltais* (Dashiell Hammett).', 'La mallette de *Pulp Fiction*, dont on ne voit jamais le contenu.', 'Le Graal des romans arthuriens.'],
      s:['Question dramatique', 'Enjeux', 'Symbole'] },
    { n:'Point de non-retour', a:'Passage du seuil · premier nœud dramatique · premier tournant',
      d:'Le moment où le personnage prend une décision ou subit un événement qui rend impossible le retour à sa vie d’avant. Il marque d’ordinaire l’entrée dans le deuxième acte.',
      u:'Ce doit être un choix (même forcé), pas un hasard. Brûlez le pont : la maison brûle, le secret est dit, le navire appareille.',
      x:['Bilbon quitte Cul-de-Sac en courant, sans même un mouchoir.', 'Raskolnikov commet le meurtre.', 'Emma cède à Rodolphe lors de la promenade à cheval, dans *Madame Bovary*.', 'Dans *Matrix*, Neo choisit la pilule rouge.'],
      s:['Élément déclencheur', 'Structure en trois actes', 'Voyage du héros'] },
    { n:'Point médian', a:'*Midpoint* · bascule centrale',
      d:'L’événement au milieu de l’histoire qui change les règles du jeu : une révélation, une fausse victoire ou une fausse défaite, qui fait passer le protagoniste de la réaction à l’action.',
      u:'C’est le remède au « ventre mou » des romans. Faites monter les enjeux, révélez quelque chose qui change le sens de l’objectif, ou accordez une victoire qui a un prix.',
      x:['*Les Apparences* (*Gone Girl*) : le changement de narratrice au milieu du livre.', '*Orgueil et Préjugés* : la première demande de Darcy et la lettre qui suit.', '*Titanic* : l’iceberg.'],
      s:['Structure en trois actes', 'Save the Cat', 'Coup de théâtre'] },
    { n:'Tout est perdu', a:'La nuit noire de l’âme · la crise',
      d:'Le point le plus bas, avant le climax : le plan a échoué, le mentor est mort, les alliés se sont éloignés, et le personnage doit affronter sa faille.',
      u:'La défaite doit découler des erreurs du personnage et l’obliger à changer (ou à refuser de changer, dans la tragédie). Plus le puits est profond, plus le climax porte.',
      x:['La chute de Gandalf dans la Moria ; la mort d’Obi-Wan ; celle de Dumbledore.', 'Elizabeth persuadée que la fuite de Lydia l’a séparée de Darcy pour toujours.', 'Edmond Dantès au château d’If, après la mort de l’abbé Faria.'],
      s:['Climax', 'Save the Cat', 'Arc de personnage', 'Mentor'] },
    { n:'Climax', a:'Point culminant · moment de vérité',
      d:'Le moment de plus forte tension, où le conflit central se tranche et où la question dramatique reçoit sa réponse.',
      u:'Le protagoniste doit être présent et décider par ses propres actes, en se servant de ce qu’il a appris. Le climax extérieur (la bataille) et le climax intérieur (le choix) doivent coïncider. Tout ce qui a été semé se récolte ici.',
      c:'Un climax résolu par un autre personnage, par le hasard ou par une règle nouvelle prive le protagoniste de son mérite.',
      x:['La destruction de l’Anneau au mont du Destin.', 'Le duel final d’*Hamlet*.', 'La seconde demande de Darcy.', 'Le dernier acte de *Cyrano de Bergerac* : la lettre lue dans la nuit tombante.'],
      s:['Dilemme', 'Dénouement', 'Deus ex machina', 'Pyramide de Freytag'] },
    { n:'Dénouement', a:'Résolution · situation finale · épilogue',
      d:'Ce qui vient après le climax : les conséquences, les fils qui se nouent, le nouvel équilibre. L’épilogue est un dénouement séparé de l’action par un saut dans le temps.',
      u:'Montrez le monde changé et le prix de la victoire. Soyez bref : la tension est retombée. Les fins ouvertes sont aussi des dénouements — elles répondent à la question centrale et laissent ouvert ce qui viendra ensuite.',
      x:['*L’Éducation sentimentale* : Frédéric et Deslauriers, vieillis, jugent que ce qu’ils ont eu de meilleur est un souvenir de jeunesse manqué.', '*Candide* : « il faut cultiver notre jardin ».', 'Le retour à la Comté dans *Le Seigneur des anneaux*.', 'Fins ouvertes : *Gatsby le Magnifique* ; *La Route* (McCarthy).'],
      s:['Climax', 'Récit circulaire', 'Pyramide de Freytag', 'Schéma quinaire'] },
    { n:'Deus ex machina', a:'« Le dieu sorti de la machine »',
      d:'Solution soudaine et extérieure à un problème sans issue : un personnage, une force ou une coïncidence que rien n’a préparé et qui règle tout. Le nom vient du théâtre grec, où un dieu descendait sur scène au moyen d’une grue.',
      u:'En règle générale, évitez-le : la solution doit naître des personnages et de ce qui a été semé. La coïncidence peut mettre les personnages dans le pétrin ; elle ne doit pas les en sortir. On l’emploie volontairement dans la comédie, la satire et la parodie.',
      x:['*Médée* (Euripide) : le char du Soleil emporte Médée.', 'L’intervention de l’exempt envoyé par le roi à la fin de *Tartuffe* (Molière).', 'Les aigles du *Hobbit* et du *Seigneur des anneaux* — sujet de débats éternels.', '*La Guerre des mondes* (H. G. Wells) : les bactéries — même si c’est ici tout le propos.'],
      s:['Fusil de Tchekhov', 'Semer et récolter', 'Climax', 'Vraisemblance'] }
  ]},
  { name:'Les personnages comme ressources', items:[
    { n:'Arc de personnage', a:'Arc de transformation · arc positif, négatif, plat',
      d:'La transformation intérieure d’un personnage au fil de l’histoire. Arc positif : il surmonte une faille ou une croyance fausse. Arc négatif : il y cède (chute, corruption, désillusion). Arc plat : il ne change pas — c’est le monde autour de lui qui change.',
      u:'Définissez ce que le personnage veut (objectif extérieur), ce dont il a besoin (vérité intérieure) et le mensonge auquel il croit. L’intrigue est la suite des pressions qui l’obligent à choisir entre les deux.',
      x:['Positif : Scrooge dans *Un chant de Noël* ; Elizabeth Bennet.', 'Négatif : Rastignac, du jeune provincial ému au « À nous deux maintenant ! » du *Père Goriot* ; Macbeth ; Michael Corleone.', 'Plat : Maigret ; Sherlock Holmes ; James Bond.'],
      t:'La fiche du Personnage montre les Scènes où il apparaît, dans l’ordre où elles sont racontées : c’est le squelette de son arc.',
      s:['Désir et besoin', 'Faute tragique', 'Tout est perdu', 'Voyage du héros'] },
    { n:'Faute tragique', a:'Hamartia · faille · blessure et mensonge',
      d:'L’erreur de jugement ou le trait de caractère qui mène le héros à sa chute (dans la tragédie) ou qu’il doit surmonter (dans les autres histoires). L’écriture contemporaine parle de la « blessure » (ce qui lui est arrivé) et du « mensonge » (ce qu’il en est venu à croire).',
      u:'La faille doit être le revers d’une qualité (le courage qui devient imprudence, la loyauté qui devient aveuglement) et doit causer les problèmes de l’intrigue.',
      x:['L’orgueil démesuré (hubris) d’Œdipe.', 'L’ambition de Macbeth ; la jalousie d’Othello ; l’indécision d’Hamlet.', 'Phèdre, que Racine dit dans sa préface « ni tout à fait coupable, ni tout à fait innocente ».', 'L’orgueil de Darcy et le préjugé d’Elizabeth.'],
      s:['Arc de personnage', 'Péripétie et reconnaissance', 'Désir et besoin'] },
    { n:'Antagoniste', a:'Opposant · adversaire · méchant',
      d:'La force qui s’oppose au protagoniste. Ce n’est pas forcément un méchant : ce peut être un rival à l’objectif légitime, une institution, la nature, ou le protagoniste lui-même. Dans le schéma actanciel, c’est l’« opposant ».',
      u:'Le meilleur antagoniste veut quelque chose de compréhensible, est plus fort que le héros au départ et l’attaque précisément à son point faible. Chaque antagoniste est le héros de sa propre histoire.',
      c:'Le méchant qui est méchant « parce que » ne fait pas peur.',
      x:['Javert dans *Les Misérables* : la loi sans miséricorde.', 'Milady de Winter dans *Les Trois Mousquetaires*.', 'Vautrin, qui tente Rastignac dans *Le Père Goriot*.', 'Iago dans *Othello* ; Big Brother dans *1984*.'],
      s:['Obstacles et complications', 'Faire-valoir', 'Antihéros', 'Schéma actanciel'] },
    { n:'Antihéros', a:'Héros sans les qualités du héros',
      d:'Protagoniste dépourvu des qualités traditionnelles du héros : lâche, égoïste, amoral, raté ou simplement ordinaire.',
      u:'Le lecteur n’a pas besoin de l’aimer ; il a besoin de le comprendre et de ne pas pouvoir en détacher les yeux. Donnez-lui une compétence, un code, de l’humour ou une vulnérabilité.',
      x:['Don Quichotte ; Lazarillo de Tormes et les picaros.', 'Meursault dans *L’Étranger* ; Bardamu dans *Voyage au bout de la nuit* (Céline).', 'Georges Duroy dans *Bel-Ami* (Maupassant).', 'Tom Ripley (Patricia Highsmith).'],
      s:['Antagoniste', 'Arc de personnage', 'Roman picaresque', 'Narrateur non fiable'] },
    { n:'Faire-valoir', a:'Personnage repoussoir · contrepoint · *foil*',
      d:'Personnage dont les traits contrastent avec ceux d’un autre (en général le protagoniste) et les rendent ainsi plus visibles.',
      u:'Placez le couple dans la même situation et donnez-lui des réponses opposées. Le faire-valoir montre ce que le protagoniste aurait pu être.',
      c:'Un faire-valoir réduit à la bêtise ne met en valeur personne : il faut qu’il ait raison de temps en temps.',
      x:['Don Quichotte et Sancho Panza.', 'Dom Juan et Sganarelle (Molière).', 'Sherlock Holmes et Watson.', 'Harry Potter et Drago Malefoy.'],
      s:['Antithèse', 'Intrigue secondaire', 'Confident'] },
    { n:'Confident', a:'Confidente · rôle codifié du théâtre classique',
      d:'Personnage à qui le protagoniste confie ses pensées et ses projets — et, à travers lui, au lecteur. La tragédie classique française en a fait un emploi à part entière.',
      u:'Il transforme le monologue en dialogue et l’exposition en scène. Il doit avoir une vie et des opinions propres : contredire est plus utile qu’acquiescer.',
      c:'Le confident qui ne fait que poser des questions n’est qu’un micro sur pattes.',
      x:['Œnone, la nourrice de Phèdre, dont les conseils précipitent la catastrophe.', 'Théramène, confident d’Hippolyte, qui fait le récit de sa mort.', 'Horatio dans *Hamlet* ; Watson.'],
      s:['Faire-valoir', 'Exposition distillée', 'Classicisme'] },
    { n:'Mentor', a:'Guide · initiateur',
      d:'Figure plus âgée ou plus sage qui prépare le héros, lui fait un don (savoir, objet, confiance) et, souvent, disparaît avant l’épreuve finale.',
      u:'Le mentor doit sortir de scène pour que le héros prouve qu’il a appris. Donnez-lui des failles, des secrets ou un passé qui compliquent la leçon.',
      x:['Mentor, sous les traits duquel Athéna guide Télémaque dans l’*Odyssée* ; c’est *Les Aventures de Télémaque* (Fénelon, 1699) qui a fait du nom un nom commun en français.', 'L’abbé Faria, qui instruit Dantès au château d’If et lui lègue un trésor.', 'Gandalf ; Dumbledore ; Obi-Wan Kenobi.'],
      s:['Voyage du héros', 'Tout est perdu', 'Personnage type'] },
    { n:'Personnage type', a:'Type · personnage plat et personnage rond (E. M. Forster) · archétype',
      d:'Le personnage type représente une classe, une profession ou un vice, avec peu de traits fixes. Forster (*Aspects du roman*, 1927) distingue les personnages plats (une seule idée, ils ne changent pas) des personnages ronds (complexes, capables de surprendre de manière convaincante).',
      u:'Les plats sont utiles : on les reconnaît tout de suite, ils servent la satire et peuplent l’arrière-plan. Les principaux doivent être ronds — donnez-leur une contradiction.',
      c:'Un type mal dosé tourne à la caricature ; un roman peuplé uniquement de types ressemble à un jeu de cartes.',
      x:['Molière : Harpagon, Tartuffe — devenus des noms communs.', 'La Bruyère, *Les Caractères* (1688) : des portraits types sous des noms grecs.', 'Balzac : le père Grandet ; Flaubert : le pharmacien Homais.'],
      s:['Caractérisation directe et indirecte', 'Allégorie', 'Conte et fable', 'Idiolecte et marques d’oralité'] },
    { n:'Intrigue secondaire', a:'Sous-intrigue · *subplot*',
      d:'Ligne d’action parallèle à l’intrigue principale, avec ses propres personnages et son propre conflit.',
      u:'La bonne intrigue secondaire reflète, contraste ou complique l’intrigue principale — elle traite le même thème sous un autre angle — et la croise à un moment décisif. Elle donne de la respiration et permet de couper sur des accroches.',
      c:'Si on peut la retirer sans que rien ne change dans l’intrigue principale, c’est un autre livre.',
      x:['*Anna Karénine* : Lévine et Kitty face à Anna et Vronski.', '*Les Misérables* : les amours de Marius et Cosette, qui finissent par entraîner Valjean sur les barricades.', '*Le Roi Lear* : Gloucester et ses fils reflètent Lear et ses filles.'],
      t:'Chaque intrigue secondaire est un Arc narratif avec sa bande ; les Branches et les convergences montrent où elle naît et où elle rejoint l’intrigue principale.',
      s:['Montage alterné', 'Entrelacement', 'Faire-valoir'] }
  ]}
]});

/* ============ TECHNIQUES NARRATIVES ============ */
SUPPORT.push({ key:'tecnicas', name:'Techniques narratives', kicker:'Technique',
  intro:'Le métier de mettre l’histoire sur la page : comment on construit une scène, comment on gère la vitesse, comment on assemble les parties, comment on entre dans la tête des personnages et quel jeu on engage avec le lecteur. Si les ressources narratives sont ce qui arrive dans l’histoire, les techniques sont la manière de le raconter.',
  groups:[
  { name:'Scène et rythme', items:[
    { n:'Montrer plutôt que dire', a:'*Show, don’t tell* · montrer, ne pas dire',
      d:'Au lieu d’affirmer un état ou une qualité (« elle était nerveuse », « il était généreux »), présenter les actions, les gestes, les paroles et les détails qui amènent le lecteur à le conclure seul.',
      u:'Montrez ce qui compte — émotions, tournants, relations — et laissez le lecteur faire l’addition. Bon test : une caméra pourrait-elle filmer cela ?',
      c:'Ce n’est pas une loi absolue : dire est indispensable pour résumer, relier les scènes et donner le contexte. Tout montrer rend le livre interminable.',
      x:['Dire : « Paul était furieux. »', 'Montrer : « Paul reposa son verre avec tant de précaution que toute la table se tut. »', 'Dire : « C’était une maison pauvre. » / Montrer : « Devant la cuisinière, le lino était usé jusqu’au ciment. »'],
      s:['Scène et sommaire', 'Sous-texte', 'Caractérisation directe et indirecte', 'Théorie de l’iceberg', 'Corrélatif objectif'] },
    { n:'Scène et sommaire', a:'Les vitesses du récit (Genette) : scène · sommaire · ellipse · pause',
      d:'Scène : le temps du récit se rapproche du temps de l’histoire — action et dialogue, moment par moment. Sommaire : on résume en quelques lignes ce qui a duré des jours ou des années. Avec l’ellipse (on saute) et la pause (l’action s’arrête pour décrire ou commenter), ce sont les quatre vitesses que Gérard Genette décrit dans *Figures III* (1972).',
      u:'Mettez en scène ce qui change quelque chose — décisions, affrontements, révélations ; en sommaire, la routine, les trajets, les transitions. Alterner les quatre vitesses donne son rythme à un livre. En français, le couple passé simple (premier plan) / imparfait (arrière-plan, habitude) épouse souvent ce partage.',
      c:'L’erreur classique : résumer les moments décisifs et mettre en scène les moments banals.',
      x:['Sommaire : « Pendant trois ans, ils s’écrivirent chaque semaine. »', 'Scène : la lettre qui cesse d’arriver — et ce qu’elle fait ce matin-là.', '*Le Père Goriot* : quelques pages de sommaire sur le passé du vermicellier, puis des scènes longues à la pension Vauquer.'],
      t:'Une Scène du Récit doit correspondre à une vraie scène ; ce qui relève du sommaire peut rester dans le résumé du Chapitre ou dans une Note.',
      s:['Ellipse narrative', 'Pause descriptive', 'Rythme narratif', 'Montrer plutôt que dire'] },
    { n:'Scène et suite', a:'*Scene and sequel* (Dwight Swain) · action et réaction',
      d:'Une paire qui se répète tout au long du livre. La scène d’action comporte un objectif, un conflit et un désastre (le personnage n’obtient pas ce qu’il voulait, ou l’obtient à un prix). La suite comporte une réaction (émotion), un dilemme (que faire maintenant ?) et une décision — qui fournit l’objectif de la scène suivante.',
      u:'Vérifiez chaque scène : que veut le personnage, qui ou quoi l’en empêche, et comment finit-elle plus mal qu’elle n’a commencé ? Raccourcissez les suites pour accélérer ; allongez-les pour approfondir le personnage.',
      x:['Scène : Anne va demander un prêt (objectif) ; le directeur d’agence est son ex-beau-frère (conflit) ; il refuse et menace de tout raconter (désastre).', 'Suite : Anne pleure dans sa voiture (réaction) ; vendre la maison ou parler à son frère ? (dilemme) ; elle appelle son frère (décision → nouvelle scène).'],
      s:['Tentatives et échecs', 'Rythme narratif', 'Obstacles et complications'] },
    { n:'Tentatives et échecs', a:'« Oui, mais… » / « Non, et en plus… »',
      d:'Chaque tentative du personnage pour résoudre son problème se termine de deux façons : il réussit, mais une nouvelle complication surgit ; ou il échoue, et la situation empire. Le « oui » et le « non » simples sont réservés à la fin.',
      u:'Demandez à chaque scène : « obtient-il ce qu’il veut ? » et choisissez « oui, mais » ou « non, et en plus ». C’est le moyen le plus simple de garantir l’escalade et d’empêcher le milieu du livre de faire du surplace.',
      x:['« Indiana Jones trouve-t-il l’Arche ? Oui, mais les nazis l’enferment dans le puits aux serpents. En sort-il ? Oui, mais l’Arche est déjà partie en camion… »', '« Réussit-elle à ouvrir le coffre ? Non — et en plus l’alarme se déclenche. »'],
      s:['Scène et suite', 'Obstacles et complications', 'Courbe de Fichte'] },
    { n:'Entrer tard, sortir tôt', a:'Couper les entrées et les sorties',
      d:'Commencer chaque scène au plus près du moment qui compte et la terminer dès que ce moment est accompli — sans arrivées, salutations, adieux ni conclusions.',
      u:'En révision, essayez de couper le premier et le dernier paragraphe de chaque scène. Finissez sur une image, une réplique ou une question, plutôt que sur une explication.',
      x:['Au lieu de « Il se gara, monta l’escalier, sonna. — Bonjour, Marthe… », commencez par : « — Depuis quand tu le sais ? demanda Marthe, sans le laisser entrer. »'],
      s:['Ellipse narrative', 'In medias res', 'Chapitres courts et cliffhangers'] },
    { n:'Ellipse narrative', a:'Saut dans le temps · ellipse temporelle',
      d:'Omission d’une période de l’histoire : la narration saute des heures, des jours ou des années. Elle peut être signalée (« Deux ans plus tard ») ou implicite (un blanc typographique).',
      u:'Sautez tout ce que le lecteur peut deviner. L’ellipse sert aussi à cacher : omettre le moment crucial (le crime, la nuit, la conversation) crée un vide que le lecteur remplit — et qui peut être révélé plus tard.',
      x:['*L’Éducation sentimentale* : « Il voyagea. » — et des années passent ; Proust admirait ce « blanc ».', 'L’os qui devient vaisseau spatial dans *2001, l’Odyssée de l’espace* : des millions d’années en un plan.', 'L’ellipse centrale des *Apparences* (*Gone Girl*).'],
      s:['Scène et sommaire', 'Entrer tard, sortir tôt', 'Ellipse (figure)', 'Paragraphe et blanc typographique'] },
    { n:'Pause descriptive', a:'Pause · digression',
      d:'Suspension de l’action pour décrire, commenter ou digresser. Dans la digression, le narrateur s’éloigne du fil de l’histoire pour réfléchir, raconter autre chose ou parler au lecteur.',
      u:'La pause freine : employez-la après un pic de tension, pour laisser respirer le lecteur, ou juste avant, pour le faire attendre. La digression est un plaisir quand la voix du narrateur vaut par elle-même.',
      c:'Une pause au mauvais moment tue le suspense ; le lecteur pressé la saute.',
      x:['*Notre-Dame de Paris* : le chapitre « Paris à vol d’oiseau ».', '*Le Père Goriot* : la longue description de la pension Vauquer avant que l’action ne commence.', '*Les Misérables* : Waterloo, l’argot, les égouts de Paris.', '*Moby Dick* : les chapitres sur les baleines et la chasse.'],
      s:['Scène et sommaire', 'Rythme narratif', 'Style essayistique', 'Description'] },
    { n:'Rythme narratif', a:'Tempo · *pacing*',
      d:'La vitesse à laquelle l’histoire avance et à laquelle le lecteur la sent passer. Il résulte de la proportion entre scène et sommaire, de la longueur des chapitres, des paragraphes et des phrases, et de la fréquence des événements.',
      u:'On accélère avec des scènes courtes, du dialogue, des phrases brèves, des coupes et des ellipses ; on ralentit avec la description, l’intériorité, les phrases longues et les suites. Alternez tension et repos : un livre qui court toujours fatigue autant qu’un livre toujours immobile.',
      x:['Thrillers : chapitres de deux pages, alternance des fils, compte à rebours.', 'Paradoxe utile : au moment de plus forte tension, ralentissez — racontez la seconde décisive en détail, au « ralenti ».'],
      t:'Dans le Récit, le nombre de Scènes par Chapitre et l’alternance des Arcs narratifs donnent une image du rythme du livre.',
      s:['Scène et sommaire', 'Chapitres courts et cliffhangers', 'Scène et suite'] },
    { n:'Chapitres courts et cliffhangers', a:'Découpage serré',
      d:'Diviser le récit en unités brèves, chacune avec son petit tournant, et les terminer en suspens.',
      u:'Chaque chapitre doit changer quelque chose et laisser une question ouverte. Coupez au milieu de l’action et reprenez plus tard. Les titres de chapitres peuvent aussi promettre, tromper ou ironiser.',
      c:'À haute dose, cela paraît mécanique. Un chapitre long et calme au bon endroit donne du poids.',
      x:['*Mémoires posthumes de Brás Cubas* (Machado de Assis) : des chapitres de quelques lignes, certains faits seulement de ponctuation.', '*Da Vinci Code* : plus de cent chapitres.', 'Le roman-feuilleton : *Les Mystères de Paris* (Eugène Sue), *Rocambole* (Ponson du Terrail).'],
      t:'Dans le Récit, faites glisser des Scènes d’un Chapitre à l’autre pour essayer différents endroits de coupe.',
      s:['Accroche et cliffhanger', 'Montage alterné', 'Rythme narratif', 'Roman-feuilleton'] }
  ]},
  { name:'Architecture du récit', items:[
    { n:'Récit enchâssé', a:'Récit-cadre · histoire dans l’histoire · niveaux narratifs',
      d:'Un récit sert de cadre à un autre, ou à plusieurs, racontés par des personnages du premier. Chaque histoire racontée dans une autre descend d’un niveau (Genette parle de récit « métadiégétique »).',
      u:'Le cadre justifie l’acte de raconter, crée un auditeur et permet de commenter l’histoire intérieure ou d’en douter. C’est le rapport entre les deux niveaux (écho, contraste, explication) qui fait sens.',
      c:'Si le cadre n’a pas de tension propre, ce n’est qu’un retard.',
      x:['*Les Mille et Une Nuits* (traduites en français par Antoine Galland à partir de 1704) ; le *Décaméron* ; l’*Heptaméron* (Marguerite de Navarre).', '*Manon Lescaut* (abbé Prévost) : le chevalier des Grieux raconte son histoire à « l’homme de qualité ».', '*Frankenstein* : les lettres de Walton contiennent le récit de Victor, qui contient celui de la créature.', '*Au cœur des ténèbres* (Conrad) : Marlow raconte, sur un bateau sur la Tamise.'],
      s:['Mise en abyme', 'Métalepse', 'Récit circulaire', 'Auteur, narrateur et narrataire'] },
    { n:'Mise en abyme', a:'Construction en abyme · récit en miroir',
      d:'Une œuvre qui contient, en petit, une image d’elle-même : une histoire, une pièce, un tableau ou un livre dans l’histoire, qui reflète l’ensemble. L’expression est d’André Gide (*Journal*, 1893), qui l’emprunte au blason, où un écu figure en petit au centre d’un écu.',
      u:'Elle condense le thème, annonce le dénouement ou démasque un personnage. Elle doit être perçue comme un reflet sans être expliquée.',
      x:['La pièce dans la pièce d’*Hamlet*, qui rejoue le crime du roi.', 'Dans la seconde partie de *Don Quichotte*, les personnages ont lu la première.', '*Les Faux-Monnayeurs* (Gide) : le romancier Édouard écrit un roman intitulé *Les Faux-Monnayeurs*.', '*Les Ménines* (Velázquez), en peinture.'],
      s:['Récit enchâssé', 'Métafiction', 'Préfiguration'] },
    { n:'Montage alterné', a:'Alternance · récit en parallèle · *cross-cutting*',
      d:'Alterner entre deux ou plusieurs lignes d’action qui se déroulent en même temps, dans des lieux ou avec des personnages différents.',
      u:'Coupez d’une ligne à l’autre à un moment de tension ; faites se répondre les lignes (le même geste, le même mot) et convergez au climax. L’alternance peut s’accélérer à mesure que la fin approche.',
      c:'Si une ligne est beaucoup plus faible, le lecteur la saute ; chacune doit avoir sa question et sa progression.',
      x:['*Madame Bovary* : les comices agricoles — Rodolphe séduit Emma pendant que l’orateur proclame les prix du fumier.', '*Guerre et Paix* : les salons et le champ de bataille.', 'Le baptême du *Parrain* : la cérémonie entrecoupée des exécutions.', '*Le Seigneur des anneaux* : Frodon et Sam d’un côté, la guerre de l’autre.'],
      t:'C’est exactement ce que montre le Récit : chaque Arc narratif sur sa bande, et l’ordre narratif (la ligne blanche) qui passe de l’une à l’autre.',
      s:['Entrelacement', 'Intrigue secondaire', 'Accroche et cliffhanger', 'Style cinématographique'] },
    { n:'Entrelacement', a:'Récit tressé · fils qui divergent et convergent',
      d:'Plusieurs lignes narratives avancent en parallèle, se séparent d’un tronc commun et se retrouvent. Le terme désigne d’abord la technique des romans arthuriens en prose du XIIIe siècle, où le narrateur « laisse » un chevalier pour en suivre un autre.',
      u:'Prévoyez les points de contact : où un fil naît d’un autre, où ils se croisent, et quelle information passe à ce croisement. Une convergence bien préparée est l’une des plus grandes récompenses pour le lecteur.',
      x:['Le *Lancelot* en prose et le cycle du *Lancelot-Graal* ; le *Roland furieux* (Arioste).', '*Le Seigneur des anneaux* : la Communauté se sépare et se retrouve.', '*Cartographie des nuages* (David Mitchell) : six histoires emboîtées et reliées.', 'Films choraux : *Magnolia*, *Babel*, *Short Cuts*.'],
      t:'Les Branches (un Arc narratif qui diverge d’un autre) et les convergences (une Scène finale qui rejoint un autre Arc narratif) sont faites pour dessiner cela.',
      s:['Montage alterné', 'Intrigue secondaire', 'Récit en mosaïque', 'Roman de chevalerie'] },
    { n:'Récit non linéaire', a:'Anachronie · chronologie éclatée',
      d:'L’ordre dans lequel les événements sont racontés ne coïncide pas avec celui dans lequel ils se sont produits : en arrière, en avant, en spirale ou en fragments mélangés. Genette appelle « anachronies » ces discordances.',
      u:'Ordonnez les épisodes selon la logique de l’émotion ou de la révélation, non selon le calendrier. Donnez au lecteur des repères (dates, âges, saisons, une coiffure) pour s’orienter.',
      c:'Le désordre doit rapporter quelque chose — suspense, ironie, sens — que l’ordre droit ne donnerait pas.',
      x:['*La Route des Flandres* (Claude Simon) : la mémoire d’une débâcle, ressassée dans tous les sens.', '*Abattoir 5* (Vonnegut) : Billy Pilgrim « décroché du temps ».', '*Memento* (Nolan) : raconté à rebours ; *Pulp Fiction* (Tarantino).', '*Pedro Páramo* (Juan Rulfo).'],
      t:'Comparez, dans la fiche de chaque Arc narratif, l’ordre narratif et l’ordre chronologique.',
      s:['Analepse', 'Prolepse', 'Récit en mosaïque', 'Récit circulaire'] },
    { n:'Récit en mosaïque', a:'Roman fragmentaire · roman choral',
      d:'Le livre se compose de fragments, d’épisodes, de voix ou de documents séparés, qui ne forment une figure que dans l’ensemble.',
      u:'Chaque fragment doit valoir par lui-même et ajouter une pièce. L’unité vient d’un lieu, d’un événement ou d’un thème commun.',
      x:['*La Vie mode d’emploi* (Perec) : un immeuble parisien, appartement par appartement.', '*Les Villes invisibles* (Calvino) ; *Marelle* (Cortázar), à lire dans plus d’un ordre.', '*Le Livre de l’intranquillité* (Pessoa).', '*Qu’avons-nous fait de nos rêves ?* (Jennifer Egan) : un chapitre est un diaporama.'],
      s:['Récit non linéaire', 'Entrelacement', 'Effet Rashomon', 'Récit épistolaire ou documentaire'] },
    { n:'Effet Rashomon', a:'Versions contradictoires',
      d:'Le même événement est raconté par plusieurs personnages, en versions incompatibles, sans que le texte tranche laquelle est vraie.',
      u:'Chaque version doit révéler celui qui la raconte — ses intérêts, sa vanité, sa culpabilité. Le lecteur devient juge.',
      x:['*Rashōmon* (Kurosawa), d’après des nouvelles d’Akutagawa.', '*Le Bruit et la Fureur* et *Tandis que j’agonise* (Faulkner).', '*Le Quatuor d’Alexandrie* (Lawrence Durrell).', '*Le Dernier Duel* (Ridley Scott) : un procès dans la France du XIVe siècle, raconté trois fois.'],
      s:['Focalisation', 'Narrateur non fiable', 'Récit en mosaïque', 'Narrateurs multiples (polyphonie)'] }
  ]},
  { name:'Intériorité, personnage et dialogue', items:[
    { n:'Monologue intérieur', a:'Monologue intérieur direct et indirect',
      d:'Reproduction de la pensée d’un personnage telle qu’il la formule pour lui-même. Il peut être direct (à la première personne, sans médiation du narrateur) ou indirect (filtré par le narrateur). Poussé jusqu’à l’association libre, il devient flux de conscience.',
      u:'Employez-le aux moments de décision, de doute ou de réaction — les suites. La pensée doit avoir la syntaxe et les obsessions du personnage, et peut contredire ce qu’il dit à voix haute.',
      c:'Les personnages qui pensent l’évidence ou répètent ce que la scène a déjà montré cassent le rythme.',
      x:['*Les lauriers sont coupés* (Édouard Dujardin, 1887), que Joyce désignait comme son modèle.', 'Le monologue de Molly Bloom à la fin d’*Ulysse* (Joyce).', '*Le Sous-lieutenant Gustl* (Schnitzler, 1900).', 'Les « tropismes » et la « sous-conversation » de Nathalie Sarraute.'],
      s:['Sous-texte', 'Scène et suite', 'Roman psychologique', 'Flux de conscience', 'Discours indirect libre', 'Distance narrative'] },
    { n:'Sous-texte', a:'Le non-dit · la sous-conversation',
      d:'Ce que les personnages veulent dire, ressentent ou cachent sous ce qu’ils disent réellement. Le dialogue est la surface ; le sous-texte est le courant.',
      u:'Faites parler les personnages d’autre chose — du temps, du dîner, d’un meuble — pendant qu’ils se disputent sur ce qu’ils ne peuvent pas nommer. Donnez-leur des objectifs opposés dans la conversation. Les gestes peuvent démentir les mots.',
      c:'Le dialogue « au premier degré », où chacun dit exactement ce qu’il ressent, sonne faux.',
      x:['*Collines comme des éléphants blancs* (Hemingway) : un couple parle d’un avortement sans jamais prononcer le mot.', 'Les pièces de Tchekhov et de Harold Pinter ; *Pour un oui ou pour un non* (Nathalie Sarraute).', '« — Il fait froid. — Tu veux ma veste ? — Non. Je veux rentrer. »'],
      s:['Théorie de l’iceberg', 'Montrer plutôt que dire', 'Monologue intérieur'] },
    { n:'Théorie de l’iceberg', a:'Théorie de l’omission (Hemingway)',
      d:'Seule une petite partie de l’histoire apparaît à la surface du texte ; le reste — le passé, les motifs, l’émotion — reste immergé et porte ce que l’on voit. L’écrivain peut omettre ce qu’il connaît bien : le lecteur le sentira.',
      u:'Sachez beaucoup plus que ce que vous racontez. Coupez les explications, les adjectifs d’émotion et les antécédents ; gardez les faits, les gestes et les répliques.',
      c:'On ne peut omettre que ce que l’on sait : omettre par ignorance laisse des trous, pas de la profondeur.',
      x:['Hemingway : dans « La Grande Rivière au cœur double », la guerre n’est jamais nommée.', 'Les nouvelles de Raymond Carver.', '*Les Vestiges du jour* (Ishiguro) : l’amour que le majordome ne nomme jamais.'],
      s:['Sous-texte', 'Montrer plutôt que dire', 'Construction d’univers', 'Minimalisme'] },
    { n:'Caractérisation directe et indirecte', a:'Portrait · caractérisation en action',
      d:'Directe : le narrateur (ou un autre personnage) dit comment est le personnage. Indirecte : le personnage se révèle par ce qu’il fait, dit, pense, porte et possède, par le milieu où il vit et par l’effet qu’il produit sur les autres.',
      u:'Présentez par un trait direct si vous voulez, puis confirmez (ou démentez) par les actes. Ce que le personnage fait sous pression vaut plus que tout ce qu’on dit de lui. Un nom, une maison, un objet caractérisent aussi.',
      x:['Directe : « C’était un homme avare. »', 'Indirecte : « Il compta les pièces deux fois avant de les tendre, et resta à les regarder dans la main de l’autre. »', '*Le Père Goriot* : Balzac décrit la pension avant sa logeuse, si bien que l’une explique l’autre.'],
      t:'La fiche du Personnage garde sa description ; les Scènes où il apparaît montrent où cette description est mise à l’épreuve.',
      s:['Montrer plutôt que dire', 'Personnage type', 'Portrait'] },
    { n:'Exposition distillée', a:'Information au compte-gouttes · *incluing*',
      d:'Donner au lecteur l’information dont il a besoin — passé, règles du monde, relations — peu à peu, dans l’action et le dialogue, au lieu de la déverser d’un bloc.',
      u:'Donnez chaque information au moment où elle manque, et de préférence comme arme dans un conflit (une dispute, un mensonge). Un nouveau venu qui ignore les codes justifie des explications. Créez d’abord la curiosité, répondez ensuite.',
      c:'À éviter : le prologue-encyclopédie et le dialogue « comme tu le sais », où deux personnages se disent ce qu’ils savent déjà tous les deux.',
      x:['Mauvais : « — Comme tu le sais, mon frère, notre père, le roi, est mort il y a dix ans à la bataille du Gué. »', 'Mieux : « — Ne me parle pas du Gué. Tu n’y étais même pas. »', 'Watson, Bilbon, Harry Potter : le nouveau venu à qui il faut tout expliquer.'],
      s:['Construction d’univers', 'In medias res', 'Confident'] },
    { n:'Construction d’univers', a:'*Worldbuilding* · création de monde',
      d:'L’invention cohérente de l’univers de l’histoire — géographie, histoire, politique, économie, croyances, technologie ou magie, et leurs règles. Cela vaut pour la fantasy et la science-fiction, mais aussi pour un roman historique ou une petite ville inventée.',
      u:'Fixez des règles et des limites et respectez-les : un système de magie vaut par ce qu’il ne peut pas faire et par ce qu’il coûte. Montrez le monde par le quotidien des personnages (ce qu’ils mangent, ce qu’ils craignent, comment ils jurent).',
      c:'Le monde est un iceberg : les neuf dixièmes restent dans les notes de l’auteur.',
      x:['La Terre du Milieu (Tolkien), avec ses langues et sa mythologie.', 'Plassans, la ville inventée des *Rougon-Macquart* ; Macondo (García Márquez) ; le comté de Yoknapatawpha (Faulkner).', '*La Horde du Contrevent* (Alain Damasio) : un monde entier organisé autour du vent.', '*Dune* (Frank Herbert) : l’écologie, la religion et la politique d’une planète.'],
      t:'Les Références et les Notes accueillent la « bible » du monde : cartes, chronologies, règles, images — associées aux Tomes et aux Arcs narratifs qu’elles concernent.',
      s:['Exposition distillée', 'Théorie de l’iceberg', 'Vraisemblance', 'Bible de série', 'Néologisme'] }
  ]},
  { name:'Jeux avec le lecteur', items:[
    { n:'Vraisemblance', a:'Suspension consentie de l’incrédulité (Coleridge)',
      d:'La qualité de paraître vrai selon les règles de l’histoire elle-même. Ce n’est pas le réalisme : un dragon peut être vraisemblable et une coïncidence réelle ne pas l’être. Le lecteur accepte de suspendre son incrédulité tant que le texte respecte les règles qu’il a posées. Le classicisme français en a fait une doctrine, avec les bienséances.',
      u:'Posez tôt le pacte — genre, ton, règles — et soyez cohérent. L’impossible s’accepte mieux que l’improbable ; les détails concrets achètent la confiance du lecteur.',
      c:'« Mais ça s’est vraiment passé comme ça ! » n’est jamais un argument : la fiction doit être plus plausible que la vie.',
      x:['Boileau, *Art poétique* (1674) : « Le vrai peut quelquefois n’être pas vraisemblable. »', 'Aristote : mieux vaut l’impossible vraisemblable que le possible invraisemblable.', '*La Métamorphose* : la prémisse admise, tout le reste est d’une logique rigoureuse.'],
      s:['Deus ex machina', 'Construction d’univers', 'Réalisme magique', 'Classicisme'] },
    { n:'Métafiction', a:'Brisure du quatrième mur · autoréférence',
      d:'Fiction qui attire l’attention sur le fait qu’elle est une fiction : le narrateur commente l’écriture, parle au lecteur, discute les personnages comme des inventions, ou le livre se prend lui-même pour sujet.',
      u:'Elle crée de la complicité, de l’humour et une réflexion sur l’acte même de raconter. Ce peut être un clin d’œil occasionnel ou l’architecture entière du livre.',
      c:'Elle rappelle au lecteur que rien de tout cela n’est réel, ce qui risque de briser l’émotion.',
      x:['*Jacques le Fataliste et son maître* (Diderot) : le narrateur menace sans cesse le lecteur de changer le cours de l’histoire.', '*Tristram Shandy* (Sterne).', '*Si par une nuit d’hiver un voyageur* (Calvino).', '*La Maîtresse du lieutenant français* (John Fowles), avec deux fins.', '*HHhH* (Laurent Binet) : le roman historique qui doute de lui-même.'],
      s:['Métalepse', 'Mise en abyme', 'Postmodernisme', 'Narrateur intrusif (commentateur)'] },
    { n:'Métalepse', a:'Transgression des niveaux narratifs (Genette)',
      d:'Transgression des frontières entre niveaux narratifs : l’auteur entre dans l’histoire, un personnage sort du livre, le narrateur intervient dans ce qu’il raconte, le lecteur est entraîné à l’intérieur. Genette a repris le terme à la rhétorique.',
      u:'Elle produit du vertige, de l’humour ou de l’inquiétude. Elle fonctionne mieux quand le texte a d’abord établi des frontières nettes.',
      x:['« Continuité des parcs » (Cortázar) : le lecteur d’un roman est la victime du crime qu’il est en train de lire.', '*Brouillard* (Unamuno) : le personnage va discuter de son destin avec l’auteur.', '*La Rose pourpre du Caire* (Woody Allen) : le personnage sort de l’écran.', '*L’Histoire sans fin* (Michael Ende).'],
      s:['Métafiction', 'Récit enchâssé', 'Mise en abyme'] },
    { n:'Défamiliarisation', a:'Singularisation · *ostranenie* (Viktor Chklovski)',
      d:'Présenter ce qui est connu comme s’il était vu pour la première fois, pour que le lecteur le voie vraiment au lieu de simplement le reconnaître.',
      u:'Décrivez sans employer le nom habituel de la chose ; adoptez le point de vue d’un enfant, d’un étranger, d’un animal ou d’un extraterrestre ; changez d’échelle. C’est le remède au lieu commun.',
      x:['*Lettres persanes* (Montesquieu) : Paris vu par deux Persans.', '*L’Ingénu* et *Micromégas* (Voltaire) : la France vue par un Huron, la Terre par un géant de Sirius.', '« Kholstomer » (Tolstoï) : la propriété expliquée par un cheval.', '*Les Voyages de Gulliver* (Swift).'],
      s:['Conte philosophique', 'Lumières', 'Cliché', 'Images sensorielles'] },
    { n:'Réalisme magique', a:'Le merveilleux dit sur le ton du quotidien',
      d:'Le surnaturel fait irruption dans un monde réaliste et il est raconté avec un naturel total, sans étonnement du narrateur ni des personnages.',
      u:'Le ton est la clé : racontez le prodige sur le même registre que le prix du pain, avec des détails exacts. Le magique est souvent la face visible d’une vérité historique, sociale ou affective.',
      c:'Ce n’est pas de la fantasy à règles expliquées : le magique ne se justifie pas.',
      x:['*Cent ans de solitude* : Remedios la Belle monte au ciel en pliant des draps.', '*Le Passe-Muraille* (Marcel Aymé, 1943) : un employé découvre qu’il traverse les murs, et l’on en parle comme d’un rhume.', '*La Maison aux esprits* (Isabel Allende) ; *Pedro Páramo* (Rulfo).'],
      s:['Vraisemblance', 'Fantastique', 'Allégorie'] },
    { n:'Écriture sous contrainte', a:'Contrainte formelle · Oulipo',
      d:'Imposer au texte une règle formelle arbitraire : ne pas employer une lettre, suivre un schéma mathématique, raconter la même histoire de quatre-vingt-dix-neuf manières.',
      u:'La contrainte oblige à trouver des solutions qui ne viendraient jamais en liberté. C’est un excellent exercice : réécrire une scène sans adjectifs, uniquement en dialogue, en une seule phrase, en exactement cent mots.',
      c:'La contrainte doit servir le texte, pas s’y substituer : si le lecteur ne voit que la prouesse, la scène est perdue.',
      x:['*Exercices de style* (Raymond Queneau, 1947) : le même incident d’autobus raconté de 99 manières.', '*La Disparition* (Georges Perec, 1969) : un roman entier sans la lettre « e » ; *Les Revenentes* (1972), avec « e » pour seule voyelle.', '*La Vie mode d’emploi* (Perec, 1978) : un immeuble parcouru selon la marche du cavalier aux échecs.'],
      s:['Oulipo', 'Récit en mosaïque', 'Pastiche et parodie'] }
  ]}
]});

/* ============ MÉTHODES NARRATIVES ============ */
SUPPORT.push({ key:'metodos', name:'Méthodes narratives', kicker:'Méthode',
  intro:'Modèles et démarches pour planifier, structurer et réviser un récit long. Les structures décrivent la forme que prennent souvent les histoires ; les méthodes de travail disent comment y arriver. Aucune n’est une recette : ce sont des cartes pour quand on est perdu et des listes de contrôle pour quand quelque chose ne marche pas. Plusieurs décrivent la même courbe sous des noms différents — l’école française a les siens (schéma quinaire, schéma actanciel) — : choisissez celui qui vous parle, ou combinez-les.',
  groups:[
  { name:'Structures d’intrigue', items:[
    { n:'Structure en trois actes', a:'Exposition · confrontation · résolution',
      d:'Le modèle le plus répandu, qui remonte à Aristote (un commencement, un milieu, une fin) et a été fixé pour le cinéma par Syd Field. Acte I (environ 25 %) : le monde, le protagoniste, l’élément déclencheur et la décision qui le lance dans l’aventure. Acte II (50 %) : obstacles croissants, point médian, crise. Acte III (25 %) : climax et dénouement.',
      u:'Bonne première carte pour n’importe quelle histoire. Repérez cinq moments — élément déclencheur, premier tournant, point médian, second tournant (tout est perdu), climax — et vérifiez qu’ils sont à peu près à leur place.',
      c:'Les pourcentages sont des moyennes, pas des lois. Le deuxième acte est long : coupez-le en deux au point médian.',
      x:['*Orgueil et Préjugés* : I — arrivée de Bingley et de Darcy ; II — refus, lettre, Pemberley, fuite de Lydia ; III — seconde demande.', '*La Guerre des étoiles* : I — Tatooine ; II — l’Étoile de la mort ; III — la bataille finale.'],
      t:'Vous pouvez utiliser les Tomes comme les actes d’une histoire, ou indiquer les actes dans le nom des Chapitres.',
      s:['Élément déclencheur', 'Point de non-retour', 'Point médian', 'Tout est perdu', 'Climax', 'Pyramide de Freytag', 'Schéma quinaire'] },
    { n:'Schéma quinaire', a:'Schéma narratif en cinq étapes (Paul Larivaille, 1974)',
      d:'Le modèle enseigné dans les écoles françaises, belges, suisses et québécoises, tiré d’un article de Paul Larivaille (revue *Poétique*, 1974). Cinq étapes : situation initiale (l’équilibre) ; élément perturbateur (ou complication) ; péripéties (les actions et réactions) ; élément de résolution ; situation finale (le nouvel équilibre).',
      u:'C’est la version la plus simple de la courbe dramatique : utile pour vérifier qu’une nouvelle, un chapitre ou une intrigue secondaire a bien un début, une rupture, un développement, un dénouement et un état final différent de l’état initial. Comparez situation initiale et situation finale : leur écart mesure ce que l’histoire a changé.',
      c:'Pensé pour analyser des contes et des récits courts, il dit peu de choses du milieu d’un roman — c’est là que les modèles plus détaillés (Save the Cat, sept points) prennent le relais.',
      x:['*Le Petit Chaperon rouge* : la fillette part chez sa grand-mère ; elle rencontre le loup ; le loup dévore la grand-mère et l’attend ; (chez Grimm) le chasseur ouvre le ventre du loup ; tout le monde est sauvé — chez Perrault, il n’y a pas d’élément de résolution, et la situation finale est la mort.', 'Une nouvelle de Maupassant : la chute est souvent l’élément de résolution, et la situation finale tient en une ligne.'],
      s:['Élément déclencheur', 'Structure en trois actes', 'Dénouement', 'Schéma actanciel', 'Nouvelle'] },
    { n:'Schéma actanciel', a:'Modèle actantiel (Algirdas Julien Greimas, 1966)',
      d:'Modèle tiré de la *Sémantique structurale* de Greimas : six fonctions (« actants ») organisent toute quête. Le Sujet désire un Objet ; le Destinateur l’y pousse (au nom d’une valeur, d’une personne, d’une institution) pour un Destinataire (celui qui en profite) ; l’Adjuvant l’aide, l’Opposant l’entrave. Un actant n’est pas forcément un personnage : ce peut être une idée, un sentiment, un objet — et un même personnage peut occuper plusieurs cases.',
      u:'Remplissez les six cases pour votre protagoniste, puis pour votre antagoniste : leurs schémas doivent se heurter. Une case vide (pas d’opposant intérieur, pas de destinataire) signale souvent une faiblesse de l’intrigue. Faites passer un personnage d’adjuvant à opposant au point médian : c’est un retournement tout trouvé.',
      c:'C’est un outil d’analyse avant d’être un outil de création : ne remplissez pas les cases au détriment des personnages.',
      x:['*Le Cid* : sujet, Rodrigue ; objet, Chimène et l’honneur ; destinateur, l’honneur familial ; opposant, le Comte (puis Chimène elle-même) ; adjuvant, le roi.', '*Le Seigneur des anneaux* : sujet, Frodon ; objet, détruire l’Anneau ; opposant, Sauron — et l’Anneau lui-même ; adjuvants, la Communauté ; Gollum, tour à tour adjuvant et opposant.'],
      s:['Antagoniste', 'Désir et besoin', 'Schéma quinaire', 'Les fonctions de Propp'] },
    { n:'Pyramide de Freytag', a:'Structure en cinq actes',
      d:'Modèle proposé par Gustav Freytag en 1863 d’après la tragédie antique et Shakespeare : exposition, action montante, climax (ici au milieu : le tournant du destin du héros), action descendante et catastrophe ou dénouement. La tragédie classique française, en cinq actes elle aussi, place l’exposition au premier acte et le dénouement au cinquième.',
      u:'Utile pour les tragédies et les histoires de chute, où le héros atteint son sommet au milieu et où la seconde moitié en tire les conséquences. Dans les histoires modernes, le climax se situe généralement beaucoup plus près de la fin.',
      x:['*Macbeth* : l’ascension jusqu’au meurtre de Banquo et au banquet (acte III) ; ensuite, la chute.', '*Roméo et Juliette* : la mort de Tybalt, au milieu, fait tout basculer.', '*Le Cid* : l’exposition et l’affront, le duel, puis la chute de tension jusqu’au dénouement suspendu par le roi.'],
      s:['Structure en trois actes', 'Climax', 'Dénouement', 'Péripétie et reconnaissance'] },
    { n:'Voyage du héros', a:'Monomythe (Joseph Campbell) · douze étapes (Christopher Vogler)',
      d:'Schéma commun aux mythes du monde entier, décrit par Campbell dans *Le Héros aux mille et un visages* (1949) et adapté à l’écriture par Vogler (*Le Guide du scénariste*). Les douze étapes : le monde ordinaire ; l’appel de l’aventure ; le refus de l’appel ; la rencontre avec le mentor ; le passage du premier seuil ; épreuves, alliés et ennemis ; l’approche de la caverne la plus profonde ; l’épreuve suprême ; la récompense ; le chemin du retour ; la résurrection ; le retour avec l’élixir.',
      u:'Excellent pour l’aventure, la fantasy et les histoires d’initiation. Lisez les étapes comme des fonctions, non comme des scènes obligatoires : elles peuvent changer d’ordre, fusionner ou manquer.',
      c:'Suivi à la lettre, il produit des histoires prévisibles.',
      x:['L’*Odyssée* ; *Le Hobbit* ; *La Guerre des étoiles* (George Lucas s’est directement inspiré de Campbell).', '*Harry Potter à l’école des sorciers* ; *Le Roi lion* ; *Matrix*.'],
      s:['Mentor', 'Point de non-retour', 'Arc de personnage', 'Story Circle', 'Voyage de l’héroïne', 'Les fonctions de Propp'] },
    { n:'Voyage de l’héroïne', a:'Maureen Murdock (1990)',
      d:'Réponse au voyage du héros, centrée sur une quête intérieure. À grands traits : séparation d’avec le féminin ; identification au masculin et réussite selon ses règles ; sentiment de vide et d’aridité ; descente ; retrouvailles avec le féminin ; guérison de la rupture ; intégration des deux parts.',
      u:'Bon modèle pour les histoires où le triomphe extérieur arrive tôt et se révèle creux, et où le vrai parcours est un chemin de réconciliation et d’identité — quel que soit le genre du personnage.',
      x:['Applications fréquentes : *Jane Eyre* ; Elsa dans *La Reine des neiges* ; *Rebelle* ; le parcours de Katniss sur l’ensemble de la trilogie.'],
      s:['Voyage du héros', 'Arc de personnage', 'Désir et besoin'] },
    { n:'Save the Cat', a:'« Sauvez le chat ! » — les quinze temps forts (*beats*) de Blake Snyder (2005)',
      d:'Liste de temps forts (*beat sheet*) créée pour le scénario et adaptée au roman par Jessica Brody : 1) image d’ouverture ; 2) thème énoncé ; 3) mise en place ; 4) catalyseur ; 5) débat ; 6) entrée dans l’acte II ; 7) intrigue B ; 8) « fun and games » (la promesse de la prémisse) ; 9) point médian ; 10) les méchants se rapprochent ; 11) tout est perdu ; 12) nuit noire de l’âme ; 13) entrée dans l’acte III ; 14) final ; 15) image finale. Le titre vient du conseil de montrer tôt le héros faisant quelque chose qui le rend sympathique — sauver un chat.',
      u:'Le plus détaillé des modèles courants : il dit ce qui doit arriver et à peu près quand. Idéal pour diagnostiquer un milieu de livre qui n’avance pas. L’« intrigue B » (souvent une relation) porte le thème.',
      c:'On lui reproche d’avoir uniformisé le cinéma commercial : servez-vous-en pour diagnostiquer, pas comme d’un moule.',
      x:['L’image d’ouverture et l’image finale doivent être l’« avant » et l’« après » du personnage.', '« Fun and games » : les cours et le Quidditch à Poudlard ; l’entraînement et le début des Jeux dans *Hunger Games*.'],
      s:['Structure en trois actes', 'Point médian', 'Tout est perdu', 'Récit circulaire', 'Structure en sept points'] },
    { n:'Story Circle', a:'Le cercle narratif de Dan Harmon',
      d:'Version condensée du voyage du héros en huit étapes disposées en cercle : 1) un personnage est dans sa zone de confort ; 2) mais il veut quelque chose ; 3) il entre dans une situation inconnue ; 4) il s’y adapte ; 5) il obtient ce qu’il voulait ; 6) mais il en paie le prix ; 7) il retourne à la situation connue ; 8) en ayant changé. La moitié haute du cercle est l’ordre ; la moitié basse, le chaos.',
      u:'Simple et rapide : il sert pour un roman, un chapitre, un épisode ou l’arc d’un personnage secondaire. Bon pour vérifier qu’il y a bien un changement.',
      x:['Employé par Harmon dans *Community* et *Rick et Morty*, épisode par épisode.', '*Le Hobbit* : le confort du trou → l’aventure (ou la poussée de Gandalf) → le monde extérieur → les épreuves → le trésor → la bataille → le retour → il n’est plus le même.'],
      s:['Voyage du héros', 'Récit circulaire', 'Arc de personnage'] },
    { n:'Structure en sept points', a:'Dan Wells',
      d:'Sept jalons : l’accroche (l’état initial, opposé à l’état final) ; premier tournant (le conflit entre en jeu) ; premier pincement (une pression qui oblige à agir) ; point médian (de la réaction à l’action) ; second pincement (le pire moment) ; second tournant (la dernière pièce nécessaire) ; résolution.',
      u:'Il se planifie à rebours : commencez par la résolution, définissez l’accroche comme son contraire, puis le point médian, les deux tournants et enfin les pincements. On peut l’appliquer à chaque fil — intrigue principale, histoire d’amour, arc intérieur — puis les tresser.',
      x:['*Harry Potter à l’école des sorciers* : accroche — l’orphelin du placard sous l’escalier ; résolution — il vainc Voldemort et a trouvé un foyer.'],
      t:'Un Arc narratif par fil, chacun avec ses sept points, permet de voir si les jalons des différents fils tombent dans les mêmes Scènes.',
      s:['Structure en trois actes', 'Planifier à partir de la fin', 'Point médian', 'Entrelacement'] },
    { n:'Courbe de Fichte', a:'*Fichtean curve* (John Gardner)',
      d:'L’histoire démarre directement dans l’action montante, sans exposition préalable, et avance par une série de crises de plus en plus graves jusqu’au climax, aux deux tiers ou aux trois quarts ; suit une brève action descendante. Le contexte est donné en chemin.',
      u:'Idéale pour les thrillers, les polars, les nouvelles et toute histoire qui doit saisir dès la première page. Chaque crise est un mini-climax avec son tournant.',
      x:['La plupart des thrillers et des romans d’aventures.', '*Le Magicien d’Oz* : tornade, sorcière, forêt, singes ailés — crise après crise.'],
      s:['In medias res', 'Tentatives et échecs', 'Obstacles et complications', 'Exposition distillée'] },
    { n:'Kishōtenketsu', a:'Structure en quatre temps d’Asie orientale',
      d:'Structure classique chinoise, coréenne et japonaise : *ki* (introduction), *shō* (développement), *ten* (tournant : un élément nouveau et inattendu, apparemment sans rapport) et *ketsu* (conclusion, qui réconcilie le tournant avec ce qui précédait). Elle ne repose pas sur un conflit central : l’intérêt naît du contraste et du changement de perspective.',
      u:'Une alternative pour les histoires contemplatives, du quotidien, de mystère doux — ou pour des chapitres et des nouvelles. Sa force est dans le tournant, et dans la façon dont il oblige à relire le début.',
      x:['Les strips en quatre cases (*yonkoma*) du manga.', 'Les films du studio Ghibli comme *Mon voisin Totoro*.', 'La construction des niveaux de certains jeux Nintendo : présenter une idée, la développer, la tordre, conclure.'],
      s:['Structure en trois actes', 'Coup de théâtre'] },
    { n:'Les sept intrigues fondamentales', a:'Christopher Booker (2004)',
      d:'Thèse selon laquelle presque toutes les histoires suivent l’un de sept schémas : vaincre le monstre ; de la misère à la richesse ; la quête ; le voyage et le retour ; la comédie ; la tragédie ; la renaissance.',
      u:'Ce n’est pas une méthode de planification, mais cela aide à comprendre quel type d’histoire on raconte et quelles attentes le lecteur apporte. Beaucoup de livres en combinent deux ou trois.',
      x:['Vaincre le monstre : *Beowulf*, *Dracula*, *Les Dents de la mer*.', 'De la misère à la richesse : *Cendrillon*, *De grandes espérances*.', 'La quête : *Le Seigneur des anneaux*. Voyage et retour : *Alice au pays des merveilles*.', 'Tragédie : *Macbeth*, *Madame Bovary*. Renaissance : *Un chant de Noël*.'],
      s:['Les 36 situations dramatiques', 'Prémisse et pitch', 'Voyage du héros'] },
    { n:'Les 36 situations dramatiques', a:'Georges Polti (1895)',
      d:'Catalogue publié par Georges Polti, qui prétend, à la suite de Carlo Gozzi (dont Goethe rapportait l’affirmation), que toutes les intrigues se ramènent à trente-six situations, chacune définie par ses éléments nécessaires — par exemple : implorer ; sauver ; la vengeance ; l’énigme ; le rapt ; l’ambition ; la rivalité de proches ; l’adultère ; la folie ; l’erreur judiciaire ; le remords ; les retrouvailles.',
      u:'Utile comme générateur d’idées et comme contrôle : à quelle situation correspond la scène centrale ? Que se passe-t-il si l’on en combine deux (une vengeance qui est aussi une erreur judiciaire) ? Les éléments de chaque situation (le persécuteur, le suppliant, la puissance hésitante…) fournissent une distribution de personnages.',
      c:'Le chiffre trente-six est plus rhétorique que scientifique ; ne vous sentez pas tenu de « tomber » dans une case.',
      x:['*Le Comte de Monte-Cristo* : l’erreur judiciaire, puis la vengeance, puis — trop tard — les retrouvailles.', '*Phèdre* : un amour criminel qui finit en accusation mensongère.'],
      s:['Les sept intrigues fondamentales', 'Prémisse et pitch', 'Dilemme'] },
    { n:'Les fonctions de Propp', a:'*Morphologie du conte* (Vladimir Propp, 1928)',
      d:'Analyse de cent contes merveilleux russes : ils se composent des mêmes trente et une « fonctions » (éloignement, interdiction, transgression, méfait ou manque, départ du héros, mise à l’épreuve par le donateur, réception de l’objet magique, combat, victoire, retour, poursuite, tâche difficile, reconnaissance, punition de l’agresseur, mariage…), toujours dans le même ordre, réparties entre sept sphères d’action : l’agresseur, le donateur, l’auxiliaire, la princesse (et son père), le mandateur, le héros et le faux héros.',
      u:'Un réservoir de motifs puissants pour la fantasy, le conte réécrit et le roman d’initiation : l’interdiction transgressée, l’épreuve du donateur, le faux héros qui revendique la victoire. Le schéma actanciel de Greimas en dérive.',
      c:'Toutes les fonctions ne sont pas présentes dans chaque conte, et l’ordre fixe vaut pour le corpus étudié, pas pour le roman moderne.',
      x:['*Cendrillon* (Perrault) : le manque (pas de robe pour le bal), le donateur (la marraine), l’objet magique, la marque (la pantoufle), la reconnaissance, les fausses héroïnes (les sœurs).'],
      s:['Schéma actanciel', 'Voyage du héros', 'Conte et fable'] },
    { n:'Quotient MICE', a:'Milieu · Idée · Personnage · Événement (Orson Scott Card)',
      d:'Quatre types de fil narratif, chacun avec son propre début et sa propre fin. Milieu : commence quand le personnage entre dans un lieu et finit quand il en sort. Idée (ou Enquête) : commence par une question et finit par la réponse. Personnage : commence par une insatisfaction envers soi et finit par un changement (ou une acceptation). Événement : commence par une rupture de l’ordre et finit par un ordre nouveau.',
      u:'Repérez les fils que vous ouvrez et fermez-les dans l’ordre inverse, comme des parenthèses imbriquées : le premier ouvert est le dernier fermé. Cela explique bien des fins décevantes — le livre a répondu à une question qui n’était pas celle qu’il avait posée.',
      x:['Milieu : *Les Voyages de Gulliver*. Idée : n’importe quel roman à énigme. Personnage : *Emma*. Événement : *Le Seigneur des anneaux*.', 'Imbrication : on ouvre un crime (Idée), puis la crise du détective (Personnage) ; on résout d’abord la crise, et enfin le crime.'],
      s:['Question dramatique', 'Entrelacement', 'Intrigue secondaire'] }
  ]},
  { name:'Méthodes de travail', items:[
    { n:'Architecte ou jardinier', a:'Planifier ou découvrir · *plotters* et *pantsers*',
      d:'Les deux pôles du processus d’écriture. L’architecte planifie tout avant d’écrire ; le jardinier plante une graine et découvre l’histoire en l’écrivant (l’image est de George R. R. Martin). La plupart des écrivains se situent quelque part entre les deux.',
      u:'Planifier épargne des réécritures et évite les impasses ; découvrir donne fraîcheur et surprise — mais se paie à la révision. Un compromis courant : connaître la fin et deux ou trois jalons, et découvrir le chemin. E. L. Doctorow comparait l’écriture à une conduite de nuit : on ne voit que jusqu’où portent les phares, mais on fait tout le voyage ainsi.',
      x:['Architectes : Zola et ses dossiers préparatoires ; J. K. Rowling et ses tableaux de chapitres ; John Irving, qui écrit d’abord la dernière phrase.', 'Jardiniers : Stephen King, qui part d’une situation et la suit ; Simenon, qui écrivait un Maigret en une dizaine de jours sans savoir à l’avance qui était le coupable, selon ses propres dires.'],
      s:['Méthode du flocon', 'Premier jet', 'Planifier à partir de la fin', 'Séquencier'] },
    { n:'Prémisse et pitch', a:'*Logline* · « Et si… ? »',
      d:'L’histoire résumée en une ou deux phrases : qui (le protagoniste), veut quoi (l’objectif), contre qui ou quoi (l’obstacle), et ce qui est en jeu. Beaucoup naissent d’une question : « Et si… ? »',
      u:'Écrivez-la avant de commencer et revenez-y quand vous vous perdez. Si elle ne tient pas en deux phrases, l’histoire n’est peut-être pas encore claire. Une bonne prémisse contient une ironie ou une tension interne.',
      x:['« Et si un homme découvrait qu’il peut traverser les murs ? » (*Le Passe-Muraille*).', '« Et si un avion atterrissait deux fois, à trois mois d’intervalle, avec les mêmes passagers ? » (*L’Anomalie*, Hervé Le Tellier).', '« Un savant donne la vie à une créature et l’abandonne ; elle vient lui demander des comptes. » (*Frankenstein*)', '« Un marin, trahi le jour de ses noces, s’évade après quatorze ans de cachot et revient, riche et méconnaissable, punir ceux qui l’ont perdu. » (*Le Comte de Monte-Cristo*)'],
      s:['Question dramatique', 'Méthode du flocon', 'Enjeux'] },
    { n:'Méthode du flocon', a:'*Snowflake Method* (Randy Ingermanson)',
      d:'Planification par expansions successives, comme une fractale, en dix étapes : 1) une phrase qui résume le roman ; 2) un paragraphe (mise en place, trois désastres, fin) ; 3) une fiche-résumé par personnage (objectif, motivation, conflit, révélation) ; 4) chaque phrase du paragraphe devient un paragraphe — synopsis d’une page ; 5) une page par personnage principal, de son point de vue ; 6) synopsis de quatre pages ; 7) fiches complètes des personnages ; 8) liste des scènes, dans un tableau ; 9) (facultatif) description de chaque scène ; 10) premier jet.',
      u:'Idéale pour qui aime planifier en gardant de la souplesse : à chaque étape on corrige les précédentes, et les problèmes de structure apparaissent avant qu’on ait écrit trois cents pages.',
      x:['Étape 1, pour *Orgueil et Préjugés* : « Une jeune femme sans fortune et à la langue bien pendue refuse l’homme le plus riche qu’elle connaisse — et découvre qu’elle s’est trompée sur lui et sur elle-même. »', 'Étape 2 : une phrase pour la mise en place, une pour chacun des trois désastres, une pour la fin.'],
      t:'L’étape 8 — la liste des scènes — c’est le Récit : une Scène par carte, avec son Personnage POV et son résumé.',
      s:['Prémisse et pitch', 'Séquencier', 'Désir et besoin', 'Architecte ou jardinier'] },
    { n:'Séquencier', a:'Plan scène par scène · *step outline* · fiches bristol',
      d:'Liste ordonnée de toutes les scènes, chacune résumée en une ou deux lignes : qui, où, ce qui change. C’est la technique des fiches punaisées au mur, chère aux scénaristes ; Nabokov écrivait ses romans sur des fiches, et Perec a construit *La Vie mode d’emploi* à partir d’un « cahier des charges » de listes.',
      u:'Écrivez une fiche par scène et battez les cartes jusqu’à ce que l’ordre fonctionne. Pour chaque scène, notez le point de vue, l’objectif, le conflit et ce qui change entre l’entrée et la sortie. Une scène où rien ne change est candidate à la coupe.',
      x:['Fiche : « 12. Cuisine, nuit. POV Anne. Elle veut que son frère signe la vente de la maison ; il refuse et révèle que leur mère lui a laissé une lettre. Ce qui change : Anne ne fait plus confiance à sa mère. »', 'Nabokov a écrit *Lolita* sur des fiches qu’il réordonnait.'],
      t:'C’est à cela que sert l’outil : chaque Scène est une carte, que l’on déplace d’un appui long, et sa bande montre à quel Arc narratif elle appartient.',
      s:['Méthode du flocon', 'Scène et suite', 'Révision par passes', 'Scène et sommaire'] },
    { n:'Planifier à partir de la fin', a:'Planification à rebours',
      d:'Commencer par le dénouement — le climax, la révélation, l’image finale — et construire à rebours tout ce qu’il faut pour y arriver.',
      u:'Indispensable pour le roman policier et toute histoire à retournement : on décide d’abord de la vérité, puis de la manière de la cacher. Demandez-vous à chaque pas : « pour que cela arrive, que doit-il s’être passé avant ? »',
      x:['Agatha Christie partait du crime et du coupable.', 'Edgar Allan Poe, dans « La Genèse d’un poème » (traduction par Baudelaire de *The Philosophy of Composition*), soutient que toute intrigue doit être élaborée en vue du dénouement.', 'John Irving écrit la dernière phrase avant de commencer.'],
      s:['Structure en sept points', 'Coup de théâtre', 'Semer et récolter', 'Préfiguration', 'Roman policier'] },
    { n:'Désir et besoin', a:'Objectif, motivation, conflit (GMC, Debra Dixon) · vouloir et besoin',
      d:'La base de tout personnage actif. Le désir : l’objectif extérieur, concret et conscient. Le besoin : la nécessité intérieure, souvent ignorée du personnage lui-même. Entre les deux, un mensonge auquel il croit. La formule GMC le résume en une phrase : « Le personnage veut [objectif] parce que [motivation], mais [conflit]. »',
      u:'Remplissez la phrase pour chaque personnage important — antagoniste compris — sur le plan extérieur comme sur le plan intérieur. Kurt Vonnegut conseillait : chaque personnage doit vouloir quelque chose, ne serait-ce qu’un verre d’eau.',
      x:['Elizabeth Bennet veut un mariage d’amour et a besoin de reconnaître ses propres préjugés.', 'Emma Bovary veut la vie des romans ; il lui faudrait voir la sienne.', 'Julien Sorel veut s’élever ; il a besoin de cesser de jouer un rôle — ce qu’il ne découvre qu’en prison.'],
      t:'La description dans la fiche du Personnage est le bon endroit pour ces trois lignes.',
      s:['Arc de personnage', 'Faute tragique', 'Enjeux', 'Dilemme', 'Schéma actanciel'] },
    { n:'Premier jet', a:'Brouillon zéro · premier brouillon rapide',
      d:'Écrire l’histoire d’un bout à l’autre le plus vite possible, sans relire ni corriger, simplement pour découvrir ce qu’elle est. Anne Lamott a défendu le droit de chacun à un premier jet exécrable ; Terry Pratchett disait que le premier jet, c’est l’auteur qui se raconte l’histoire à lui-même.',
      u:'Fixez-vous un objectif quotidien, ne revenez pas en arrière, et laissez des marques là où il manque quelque chose (« [vérifier la date] », « [scène de la dispute ici] »). Le défi des 50 000 mots en un mois, popularisé par le NaNoWriMo, repose sur ce principe.',
      c:'Un premier jet n’est pas un livre : c’est une matière première. Le vrai travail commence à la révision.',
      x:['Habitude courante : écrire « XXX » à la place du mot ou du fait qui manque, et continuer.'],
      s:['Architecte ou jardinier', 'Révision par passes'] },
    { n:'Révision par passes', a:'Plan inversé · réécriture par couches',
      d:'Réviser en plusieurs passes, chacune avec un seul objectif, du plus grand au plus petit : d’abord la structure (ordre, coupes, trous), puis les scènes (objectif, conflit, tournant), les personnages (cohérence, voix), et à la fin seulement la phrase (rythme, répétitions, orthographe). Le plan inversé consiste à faire le séquencier de ce qui est réellement écrit, pour voir la forme réelle du livre.',
      u:'Laissez reposer le texte quelques semaines. Faites le plan inversé et comparez-le au plan prévu. Ne polissez pas les phrases de scènes qui seront peut-être coupées. Lisez à voix haute à la dernière passe — Flaubert « gueulait » ses phrases dans son « gueuloir » pour en éprouver le rythme.',
      x:['Questions de la première passe : l’histoire commence-t-elle au bon endroit ? Chaque scène change-t-elle quelque chose ? Ce qui a été semé est-il récolté ? Des personnages peuvent-ils fusionner ?', 'Questions de la dernière : des mots répétés sur la même page ? Toutes les phrases commencent-elles de la même façon ?'],
      t:'Recréer dans le Récit le livre déjà écrit — Scène par Scène, avec POV et Arc narratif — est un plan inversé : les déséquilibres sautent aux yeux (un fil qui disparaît pendant dix Chapitres, un Personnage qui ne revient jamais).',
      s:['Séquencier', 'Premier jet', 'Semer et récolter', 'Entrer tard, sortir tôt'] },
    { n:'Les cinq commandements de la scène', a:'*Story Grid* (Shawn Coyne)',
      d:'Selon cette méthode d’analyse, toute unité narrative — scène, séquence, acte, livre — comporte cinq éléments : élément déclencheur ; complication progressive qui culmine en un tournant ; crise (un choix difficile) ; climax (le choix fait) ; résolution.',
      u:'Liste de contrôle pour les scènes qui « ne marchent pas » : il manque presque toujours la crise — le personnage n’a pas vraiment à choisir. La méthode demande aussi de connaître le genre et les scènes obligatoires qu’en attend le lecteur.',
      x:['Scènes obligatoires : la première rencontre et la preuve d’amour dans une romance ; la découverte du corps et la révélation du coupable dans un roman policier ; le héros à la merci du méchant dans un thriller.'],
      s:['Scène et suite', 'Dilemme', 'Climax', 'Élément déclencheur'] },
    { n:'Bible de série', a:'Dossier de continuité',
      d:'Le document qui consigne tout ce qui est déjà fixé dans l’univers de l’histoire : fiches de personnages (âge, apparence, tics, ce qu’ils savent et depuis quand), chronologie, cartes, règles du monde, vocabulaire, décisions prises.',
      u:'Indispensable pour les sagas, les séries et les histoires à nombreux personnages : elle évite les yeux qui changent de couleur et les morts qui reviennent. Mettez-la à jour pendant l’écriture, pas après.',
      x:['L’arbre généalogique des Rougon-Macquart et les dossiers préparatoires de Zola, pour vingt romans.', 'Les personnages reparaissants de *La Comédie humaine* : Balzac devait savoir où en était Rastignac dans chaque livre.', 'Les chronologies et appendices de Tolkien ; les « bibles » remises aux scénaristes des séries télévisées.'],
      t:'L’outil est en partie cela : fiches des Personnages, Arcs narratifs avec les deux ordres, Références et Notes associées à chaque élément, sur plusieurs Tomes.',
      s:['Construction d’univers', 'Séquencier', 'Entrelacement'] },
    { n:'Le thème comme question', a:'Argument thématique',
      d:'Le thème est ce dont l’histoire parle sous l’intrigue. Il fonctionne mieux formulé comme une question ouverte (« Jusqu’où peut-on aller par amour ? ») que comme une leçon (« L’amour triomphe de tout »).',
      u:'Faites donner par les personnages des réponses différentes à la même question — le protagoniste, l’antagoniste, les intrigues secondaires — et laissez le climax les mettre à l’épreuve. Souvent, on ne découvre le thème qu’à la fin du premier jet ; on le renforce à la révision, par des motifs et des échos.',
      c:'Un personnage qui énonce la morale de l’histoire transforme le roman en sermon.',
      x:['*Madame Bovary* : que deviennent les rêves appris dans les livres quand ils rencontrent la vie ?', '*La Peste* (Camus) : comment agir quand on ne peut pas gagner ?', '*Frankenstein* : que doit le créateur à sa créature ?'],
      s:['Intrigue secondaire', 'Prémisse et pitch', 'Motif récurrent', 'Symbole'] }
  ]}
]});

/* ============ STYLES NARRATIFS ============ */
SUPPORT.push({ key:'estilos-narrativos', name:'Styles narratifs', kicker:'Style narratif',
  intro:'Les grandes manières de raconter une histoire : les courants littéraires (ce qu’une époque a cru qu’un roman devait être), les genres narratifs (le type de livre et ce que le lecteur en attend) et les manières d’écrire la prose. Les connaître aide à choisir en connaissance de cause — et à mélanger à bon escient. Les exemples privilégient la littérature de langue française (France, Belgique, Suisse, Québec), sans oublier les classiques que tout écrivain lit. Certaines esthétiques (réalisme et naturalisme, gothique, baroque, roman noir, réalisme magique) ont déjà leur fiche ailleurs dans ce guide : elles sont reliées ici sans être répétées.',
  groups:[

  { name:'Courants et époques', items:[
    { n:'Classicisme', a:'France, XVIIe siècle (vers 1660–1685)',
      d:'Idéal d’ordre, de clarté et de mesure, fondé sur l’imitation des Anciens, la raison, la vraisemblance et les bienséances. Au théâtre, la règle des trois unités ; en prose, l’analyse morale et psychologique, la concision, la litote. *La Princesse de Clèves* (1678) en tire le premier grand roman d’analyse.',
      u:'Héritage précieux pour qui veut une prose tenue : dire beaucoup en peu de mots, laisser la passion se lire dans la retenue, peindre l’âme humaine en traits généraux. Une intrigue resserrée — peu de personnages, une crise, des choix — et une psychologie fine restent un modèle pour le roman intimiste.',
      c:'La retenue peut virer à la froideur, et l’abstraction morale (« l’amour », « la gloire ») à la sécheresse. Il faut, sous la mesure, une passion qui brûle.',
      x:['Madame de La Fayette, *La Princesse de Clèves* (1678).', 'Racine, *Phèdre* (1677) ; La Fontaine, *Fables* (1668–1694).', 'La Rochefoucauld, *Maximes* (1665) ; La Bruyère, *Les Caractères* (1688).'],
      s:['Roman psychologique', 'Vraisemblance', 'Dilemme', 'Confident', 'Litote'] },
    { n:'Lumières', a:'XVIIIe siècle · le siècle de Voltaire et de Diderot',
      d:'Siècle de la raison critique, de la tolérance et de l’esprit de libre examen. Le roman y devient un laboratoire : conte philosophique, roman épistolaire, roman libertin, récit expérimental qui discute avec son lecteur.',
      u:'Il enseigne à faire passer des idées par la fiction sans sermonner : le regard naïf qui démasque l’absurde, l’ironie, la forme épistolaire qui confronte les points de vue, le narrateur qui joue avec les attentes du lecteur.',
      c:'La fiction à idées tourne vite à la démonstration. Les grandes œuvres du siècle sont d’abord drôles, cruelles et rapides.',
      x:['Montesquieu, *Lettres persanes* (1721) ; Voltaire, *Candide* (1759).', 'Rousseau, *Julie ou la Nouvelle Héloïse* (1761) ; Laclos, *Les Liaisons dangereuses* (1782).', 'Diderot, *Jacques le Fataliste et son maître* (écrit vers 1765–1780).'],
      s:['Conte philosophique', 'Défamiliarisation', 'Métafiction', 'Style ironique'] },
    { n:'Romantisme', a:'France, vers 1820–1850',
      d:'Mouvement qui place au centre la sensibilité, l’individu, la nature, l’histoire nationale et la liberté de l’art. En France, il s’affirme avec la préface de *Cromwell* (Hugo, 1827) et la « bataille » d’*Hernani* (1830) ; il donne le roman historique de Hugo et de Dumas, le roman personnel de Chateaubriand, Musset ou George Sand.',
      u:'Héritage utile aujourd’hui : des personnages mus par des passions absolues, le conflit entre l’individu et la société, des paysages qui reflètent l’état d’âme, la fascination pour le Moyen Âge et les ruines, le mélange du sublime et du grotesque, le destin tragique. Il fonctionne dans le roman historique, le drame passionnel et toute histoire d’amour impossible.',
      c:'L’excès romantique (larmes, évanouissements, coïncidences providentielles) a mal vieilli ; gardez l’intensité, pas les maniérismes. Le personnage romantique a besoin d’un monde qui lui résiste, sinon la passion n’est que bruit.',
      x:['Chateaubriand, *René* (1802) ; Musset, *La Confession d’un enfant du siècle* (1836).', 'Victor Hugo, *Notre-Dame de Paris* (1831).', 'George Sand, *Indiana* (1832) ; Alexandre Dumas, *Le Comte de Monte-Cristo* (1844–1846).'],
      s:['Roman historique', 'Roman-feuilleton', 'Réalisme et naturalisme', 'Gothique'] },
    { n:'Symbolisme et décadentisme', a:'Fin du XIXe siècle',
      d:'Réaction contre le réalisme et le naturalisme : au lieu de décrire le monde, le suggérer — par le symbole, la musique de la phrase, les correspondances entre les sensations. Le manifeste de Jean Moréas paraît dans *Le Figaro* en 1886. Le décadentisme y ajoute le goût de l’artifice, de la maladie, de l’ennui et des fins de règne. La Belgique y tient une place majeure (Maeterlinck, Rodenbach, Verhaeren).',
      u:'Utile pour les récits d’atmosphère : des personnages qui se dissolvent dans ce qu’ils ressentent, des décors qui sont des états d’âme, des phrases rythmées et des images récurrentes. *Bruges-la-Morte* montre comment une ville entière peut devenir le miroir d’un deuil.',
      c:'Cela peut devenir vague et précieux. La suggestion ne fonctionne que s’il y a du concret derrière le symbole.',
      x:['Huysmans, *À rebours* (1884), le bréviaire de la décadence.', 'Georges Rodenbach, *Bruges-la-Morte* (1892).', 'Villiers de l’Isle-Adam, *L’Ève future* (1886) ; Maeterlinck, *Pelléas et Mélisande* (1892), théâtre.'],
      s:['Style lyrique', 'Symbole', 'Atmosphère', 'Prose poétique'] },
    { n:'Modernisme', a:'Premières décennies du XXe siècle',
      d:'Rupture avec les formes héritées : fragmentation, points de vue multiples, flux de conscience, temps subjectif, expérimentation sur la langue. L’étiquette est surtout anglo-saxonne, mais la France a ses grands modernes : Proust et le temps de la mémoire, Gide et le roman qui se regarde écrire, Larbaud et le monologue intérieur.',
      u:'Le modernisme a donné au roman les outils de l’intériorité : le monologue intérieur, le changement de focalisation, le temps psychologique au lieu du temps chronologique. Employez-les quand l’histoire se joue davantage dans la tête des personnages que dans les événements.',
      c:'Imiter la difficulté des modernes sans leur nécessité donne des textes obscurs. Les grands modernes sont difficiles parce que ce qu’ils veulent dire ne tient pas dans la forme traditionnelle.',
      x:['Marcel Proust, *À la recherche du temps perdu* (1913–1927).', 'André Gide, *Les Faux-Monnayeurs* (1925) ; Valery Larbaud, *Amants, heureux amants* (1923).', 'Virginia Woolf, *Mrs Dalloway* (1925) ; James Joyce, *Ulysse* (1922).'],
      s:['Monologue intérieur', 'Récit non linéaire', 'Roman psychologique', 'Flux de conscience'] },
    { n:'Surréalisme', a:'Paris, à partir de 1924 · aussi en Belgique et au Québec',
      d:'Mouvement fondé par André Breton (*Manifeste du surréalisme*, 1924), qui veut libérer l’imagination du contrôle de la raison : le rêve, le hasard objectif, l’inconscient, l’écriture automatique, l’humour noir. Il a un rameau belge (Magritte, Scutenaire) et un écho québécois avec les automatistes du *Refus global* (1948).',
      u:'Dans le récit, le surréalisme sert aux scènes de rêve, à la logique onirique d’une nouvelle, aux images inattendues qui révèlent ce que le personnage ne sait pas qu’il ressent, à la déambulation urbaine guidée par le hasard. La forme courte est son terrain naturel.',
      c:'L’insolite pour l’insolite s’épuise vite. Même un récit surréaliste a besoin d’une logique interne et d’un centre émotionnel.',
      x:['André Breton, *Nadja* (1928).', 'Louis Aragon, *Le Paysan de Paris* (1926).', 'Breton et Soupault, *Les Champs magnétiques* (1920), premier texte d’écriture automatique.'],
      s:['Réalisme magique', 'Défamiliarisation', 'Absurde', 'Humour noir'] },
    { n:'Existentialisme', a:'Milieu du XXe siècle · et la littérature de l’absurde',
      d:'Courant philosophique et littéraire centré sur la liberté, l’angoisse, l’absurdité de l’existence et la responsabilité de choisir sans garanties. Sartre et Simone de Beauvoir en sont les figures ; Camus, qui refusait l’étiquette, développe une pensée voisine, celle de l’absurde.',
      u:'Placez un personnage devant un choix qu’aucune règle extérieure ne tranche. La tension vient de la conscience : ce que le personnage sait de lui-même et du monde, et ce qu’il en fait. Cela fonctionne dans des récits dépouillés, à la première personne, au ton réflexif.',
      c:'Le risque est le personnage-thèse qui discourt sur l’absurde au lieu de le vivre. La situation concrète (un crime, une épidémie, une plage écrasée de soleil) doit porter l’idée.',
      x:['Jean-Paul Sartre, *La Nausée* (1938).', 'Albert Camus, *L’Étranger* (1942) et *La Peste* (1947).', 'Simone de Beauvoir, *L’Invitée* (1943).'],
      s:['Roman psychologique', 'Littérature engagée', 'Style essayistique', 'Dilemme', 'Absurde'] },
    { n:'Littérature engagée', a:'Roman social · roman à thèse · de Zola à Sartre',
      d:'Une littérature qui prend parti dans les combats de son temps. Sartre la théorise dans *Qu’est-ce que la littérature ?* (1948), mais la tradition remonte à Hugo et à Zola (*Germinal*, puis « J’accuse… ! »). Elle va du roman révolutionnaire (Malraux) à la littérature de la Résistance et au roman social québécois.',
      u:'Utile pour les histoires dont le protagoniste est un groupe, une classe ou une communauté, et où le milieu économique et politique décide du destin des personnages. Elle enseigne à se documenter (Zola descend dans la mine) et à donner une voix à ceux qui n’en avaient pas.',
      c:'La thèse affichée transforme les personnages en symboles et le roman en tract. Les meilleurs livres engagés racontent l’injustice à travers des personnes concrètes et une écriture travaillée.',
      x:['Émile Zola, *Germinal* (1885).', 'André Malraux, *La Condition humaine* (1933).', 'Vercors, *Le Silence de la mer* (1942), publié clandestinement.', 'Gabrielle Roy, *Bonheur d’occasion* (1945), Montréal ouvrier pendant la guerre.'],
      s:['Réalisme et naturalisme', 'Existentialisme', 'Roman de mœurs', 'Récit en mosaïque'] },
    { n:'Nouveau Roman', a:'France, années 1950–1960 · Éditions de Minuit',
      d:'Courant français (Alain Robbe-Grillet, Nathalie Sarraute, Michel Butor, Claude Simon, autour des Éditions de Minuit) qui refuse le personnage psychologique et l’intrigue traditionnelle : descriptions minutieuses et objectives, répétitions, temps brouillé, lecteur chargé de reconstruire l’histoire. Ses manifestes : *L’Ère du soupçon* (Sarraute, 1956) et *Pour un nouveau roman* (Robbe-Grillet, 1963).',
      u:'Utile comme laboratoire : la description « objective » qui trahit une obsession, la répétition d’une scène avec de petites variations, le roman à la deuxième personne (*La Modification*, de Butor). Les « tropismes » de Sarraute — ces mouvements infimes sous les paroles — sont une leçon de sous-texte.',
      c:'Sur un roman entier, il exige beaucoup du lecteur. Aujourd’hui, on l’emploie surtout par morceaux, comme technique.',
      x:['Alain Robbe-Grillet, *La Jalousie* (1957).', 'Michel Butor, *La Modification* (1957), à la deuxième personne.', 'Nathalie Sarraute, *Tropismes* (1939) ; Claude Simon, *La Route des Flandres* (1960).'],
      s:['Défamiliarisation', 'Sous-texte', 'Écriture sous contrainte', 'Style cinématographique', 'Deuxième personne'] },
    { n:'Oulipo', a:'Ouvroir de littérature potentielle (fondé en 1960)',
      d:'Groupe fondé en 1960 par Raymond Queneau et François Le Lionnais, réunissant écrivains et mathématiciens autour de l’écriture sous contrainte. Membres célèbres : Georges Perec, Italo Calvino, Jacques Roubaud, Harry Mathews, et plus récemment Hervé Le Tellier (*L’Anomalie*, prix Goncourt 2020).',
      u:'L’Oulipo montre qu’une règle formelle peut produire du romanesque, de l’émotion et même du roman populaire. Empruntez-lui des contraintes pour débloquer un chapitre, structurer un livre (une contrainte par partie) ou cacher un sens second sous la forme — dans *La Disparition*, la lettre absente dit aussi les disparus.',
      c:'Le jeu formel peut devenir un club fermé ; la contrainte doit rester invisible au lecteur qui ne la cherche pas, ou faire partie du plaisir.',
      x:['Raymond Queneau, *Zazie dans le métro* (1959) et *Exercices de style* (1947).', 'Georges Perec, *La Disparition* (1969) et *La Vie mode d’emploi* (1978).', 'Italo Calvino, *Si par une nuit d’hiver un voyageur* (1979).'],
      s:['Écriture sous contrainte', 'Postmodernisme', 'Récit en mosaïque'] },
    { n:'Postmodernisme', a:'Depuis les années 1960–1970',
      d:'Une fiction qui joue avec elle-même : métafiction, parodie, intertextualité, mélange des genres et des registres, méfiance envers les grands récits, réécriture ironique de l’Histoire. En France, on parle moins de « postmodernisme » que de jeux avec les genres (Echenoz), de fiction critique (Chevillard) ou de roman historique réflexif (Binet).',
      u:'Employez-le pour réécrire l’Histoire depuis ses marges (ceux qui n’apparaissent pas dans les manuels), pour des narrateurs qui commentent leur propre récit, pour des collages de documents et de voix, pour détourner un genre populaire.',
      c:'L’ironie et l’autoréférence en excès éloignent le lecteur de l’histoire. Les grands romans postmodernes sont d’abord de bonnes histoires.',
      x:['Italo Calvino, *Si par une nuit d’hiver un voyageur* (1979) ; Umberto Eco, *Le Nom de la rose* (1980).', 'Jean Echenoz, *Cherokee* (1983), le roman policier détourné.', 'Laurent Binet, *HHhH* (2010).'],
      s:['Métafiction', 'Oulipo', 'Roman historique', 'Pastiche et parodie', 'Intertextualité'] },
    { n:'Minimalisme', a:'Hemingway, Carver · les « romanciers impassibles » de Minuit',
      d:'Une prose réduite à l’essentiel : phrases courtes, vocabulaire simple, peu d’adjectifs, dialogues secs, presque aucune explication psychologique. Le sens est dans le non-dit. Il vient d’Hemingway et de sa théorie de l’iceberg, et trouve chez Raymond Carver son modèle pour la nouvelle. En France, dans les années 1980, on a qualifié d’« impassibles » ou de « minimalistes » Jean Echenoz, le Belge Jean-Philippe Toussaint ou Christian Oster.',
      u:'Excellent pour les nouvelles et pour les vies ordinaires, où l’émotion est contenue. Coupez tout ce que le lecteur peut déduire ; laissez parler les gestes et les silences.',
      c:'Mal fait, ce n’est que pauvreté de langue et scènes sans tension. Le minimalisme exige un sous-texte fort ; sans lui, il n’y a rien sous la surface.',
      x:['Raymond Carver, *Parlez-moi d’amour* (*What We Talk About When We Talk About Love*, 1981).', 'Jean-Philippe Toussaint, *La Salle de bain* (1985).', 'Ernest Hemingway, « Collines comme des éléphants blancs » (1927).'],
      s:['Théorie de l’iceberg', 'Sous-texte', 'Style sobre', 'Phrase courte'] },
    { n:'Autofiction', a:'Roman autobiographique · depuis les années 1970',
      d:'Récit où l’auteur se met en scène comme personnage, sous son nom ou un nom proche, en mêlant faits de sa vie et invention. Le terme est de Serge Doubrovsky (*Fils*, 1977). Le genre est devenu l’un des plus vivants de la littérature française.',
      u:'Il donne à la fiction la force du témoignage. Il fonctionne quand le « je » est traité comme un personnage — avec ses défauts, ses angles morts et un parcours — et non comme un journal intime.',
      c:'Questions éthiques et juridiques face à des personnes réelles reconnaissables. Et le risque du nombrilisme : la vie de l’auteur n’intéresse le lecteur que transformée en histoire.',
      x:['Serge Doubrovsky, *Fils* (1977).', 'Hervé Guibert, *À l’ami qui ne m’a pas sauvé la vie* (1990).', 'Annie Ernaux, *Les Années* (2008) — qui préfère parler d’« auto-socio-biographie » ; Emmanuel Carrère, *Le Royaume* (2014).'],
      s:['Narrateur non fiable', 'Métafiction', 'Style de reportage', 'Première personne — protagoniste'] }
  ]},

  { name:'Genres narratifs', items:[
    { n:'Roman', a:'Le récit long',
      d:'Récit long en prose, avec plusieurs personnages, actions et lieux, qui peut suivre une vie, une famille ou une époque. C’est le genre le plus souple : il absorbe tous les autres.',
      u:'Il demande une question qui tienne des centaines de pages et un développement des personnages. Servez-vous des fiches de structure (trois actes, voyage du héros, schéma quinaire) pour l’architecturer et de l’outil pour suivre Tomes, Chapitres, Scènes et Arcs narratifs.',
      c:'Un roman n’est pas une nouvelle étirée : il lui faut des intrigues secondaires, des variations de rythme et des personnages qui changent.',
      x:['Gustave Flaubert, *Madame Bovary* (1857).', 'Victor Hugo, *Les Misérables* (1862).', 'Marguerite Yourcenar, *Mémoires d’Hadrien* (1951).'],
      t:'Chaque Tome peut être un roman d’une série, ou une partie d’un long roman.',
      s:['Court roman', 'Nouvelle', 'Structure en trois actes', 'Intrigue secondaire'] },
    { n:'Court roman', a:'*Novella* · récit',
      d:'Récit d’étendue moyenne, entre la nouvelle et le roman : une action principale, peu de personnages, un temps resserré, mais plus de développement que la nouvelle. Le français n’a pas de mot fixe : on dit « court roman », « récit » (Gide donnait ce nom à *L’Immoraliste* et à *La Porte étroite*), parfois « nouvelle » ou, à l’anglaise, *novella*.',
      u:'Bon format pour une seule crise vécue en profondeur, pour une voix forte, pour des histoires qui perdraient de leur force à être allongées.',
      c:'N’y ajoutez pas des intrigues secondaires pour « faire roman » : la concentration est sa vertu.',
      x:['André Gide, *L’Immoraliste* (1902).', 'Stefan Zweig, *Le Joueur d’échecs* (1943).', 'Tolstoï, *La Mort d’Ivan Ilitch* (1886) ; Hemingway, *Le Vieil Homme et la Mer* (1952).'],
      s:['Roman', 'Nouvelle', 'Roman psychologique'] },
    { n:'Nouvelle', a:'Le récit bref · la nouvelle à chute',
      d:'Récit court, centré sur un moment, une situation ou une révélation, avec peu de personnages et une grande économie de moyens. Il se lit d’une traite, et mise donc tout sur un effet. La tradition française, de Mérimée à Maupassant, a cultivé la « nouvelle à chute », dont la dernière phrase renverse ou éclaire tout.',
      u:'Commencez tard, finissez tôt ; chaque phrase doit servir l’effet final. La nouvelle vit souvent d’un changement minime : quelqu’un comprend quelque chose, ou ne peut plus l’ignorer (l’« épiphanie » de Joyce). Si vous visez la chute, semez-la dès la première page.',
      c:'Une nouvelle n’est pas le premier chapitre d’un roman. Et une chute qui ne repose sur rien n’est qu’un tour de passe-passe.',
      x:['Prosper Mérimée, *Mateo Falcone* (1829).', 'Guy de Maupassant, « La Parure » (1884), modèle de la nouvelle à chute.', 'Marcel Aymé, *Le Passe-Muraille* (1943).', 'Tchekhov, « La Dame au petit chien » (1899) ; Borges, *Fictions* (1944).'],
      s:['Court roman', 'Entrer tard, sortir tôt', 'Minimalisme', 'Coup de théâtre', 'Conte et fable', 'Excipit'] },
    { n:'Chronique', a:'Texte bref sur le quotidien · tradition journalistique et littéraire',
      d:'Texte court, publié surtout dans la presse, qui part du quotidien — un épisode, une observation, un souvenir — pour aboutir à une réflexion, souvent avec humour ou lyrisme. Au Moyen Âge, la chronique est l’œuvre d’histoire (Froissart). Stendhal sous-titre *Le Rouge et le Noir* « Chronique de 1830 » : le mot dit alors le roman ancré dans son temps.',
      u:'La chronique entraîne la voix : ton personnel, rythme, sens du détail. Dans le roman, une voix de chroniqueur donne des narrateurs proches, causeurs, ironiques.',
      c:'Dans un roman, le ton de chronique peut disperser le récit en digressions ; employez-le comme couleur, non comme structure.',
      x:['Jean Froissart, *Chroniques* (XIVe siècle).', 'Alexandre Vialatte, ses chroniques dans *La Montagne* (1952–1971).', 'Colette, ses chroniques de presse réunies en volumes.'],
      s:['Narrateur intrusif (commentateur)', 'Style ironique', 'Style essayistique', 'Ton'] },
    { n:'Roman d’apprentissage', a:'Roman de formation · *Bildungsroman* · roman d’éducation',
      d:'Roman qui suit la formation d’un personnage — en général de l’enfance ou de la jeunesse à l’âge adulte — à travers des expériences, des erreurs, des pertes et des découvertes. La tradition française a un versant désenchanté : l’apprentissage y est souvent celui des illusions perdues.',
      u:'L’arc du personnage est l’intrigue même. Choisissez bien les étapes (le départ de la maison, le premier amour, la perte, la désillusion) et ce que le personnage apprend à chacune.',
      c:'Une somme d’épisodes ne fait pas une formation : chaque étape doit changer le personnage, et la fin doit montrer qui il est devenu.',
      x:['Goethe, *Les Années d’apprentissage de Wilhelm Meister* (1795–1796).', 'Balzac, *Illusions perdues* (1837–1843) ; Flaubert, *L’Éducation sentimentale* (1869).', 'Alain-Fournier, *Le Grand Meaulnes* (1913) ; Dickens, *De grandes espérances* (1861).'],
      s:['Arc de personnage', 'Voyage du héros', 'Désir et besoin'] },
    { n:'Roman historique', a:'Fiction dans un passé documenté',
      d:'Roman situé dans une époque historique reconstituée, où des personnages inventés côtoient des événements et parfois des figures réels. Il naît avec Walter Scott ; en France, il s’épanouit avec Vigny (*Cinq-Mars*, 1826), Hugo et Dumas.',
      u:'Documentez-vous à fond (mœurs, objets, langue, prix, distances), puis cachez la recherche dans les scènes. Choisissez un angle que l’Histoire officielle n’a pas montré. Yourcenar, dans les « Carnets de notes » de *Mémoires d’Hadrien*, décrit l’effort de « refaire du dedans » une époque. Pour la langue, voyez la section sur le français d’autrefois.',
      c:'Les anachronismes de mentalité sont plus graves que ceux d’objets : des personnages aux valeurs d’aujourd’hui dans une époque qui ne les avait pas. L’excès d’information historique bloque le récit.',
      x:['Alexandre Dumas, *Les Trois Mousquetaires* (1844).', 'Marguerite Yourcenar, *Mémoires d’Hadrien* (1951) et *L’Œuvre au noir* (1968).', 'Maurice Druon, *Les Rois maudits* (1955–1977) ; Hilary Mantel, *Le Conseiller* (*Wolf Hall*, 2009).'],
      s:['Construction d’univers', 'Postmodernisme', 'Romantisme', 'Écrire un roman historique', 'Archaïsme'] },
    { n:'Roman policier', a:'Polar · roman à énigme · roman noir',
      d:'Récit organisé autour d’un crime et de son élucidation. Le roman à énigme (*whodunit*) invite le lecteur à découvrir le coupable ; le roman noir s’intéresse à la violence, à la ville et à la corruption — la « Série noire » de Gallimard (1945) lui a donné son nom en français. Le roman de procédure suit l’enquête policière pas à pas.',
      u:'Planifiez le crime de la fin vers le début : ce qui s’est passé, qui savait, quels indices sont restés. Distribuez vrais et faux indices avec loyauté (le lecteur doit pouvoir deviner). Les Arcs narratifs de l’outil aident à séparer la chronologie du crime de l’ordre de l’enquête.',
      c:'La solution doit être préparée dans le texte ; un coupable surgi à la fin sans indices, c’est de la triche. Les détectives sans failles n’intéressent personne.',
      x:['Edgar Allan Poe, « Double assassinat dans la rue Morgue » (1841, traduit par Baudelaire).', 'Émile Gaboriau, *L’Affaire Lerouge* (1866) ; Gaston Leroux, *Le Mystère de la chambre jaune* (1907).', 'Georges Simenon, la série des Maigret (à partir de 1931).', 'Agatha Christie, *Le Crime de l’Orient-Express* (1934) ; Fred Vargas, *Pars vite et reviens tard* (2001).'],
      t:'Utilisez un Arc narratif pour la chronologie réelle du crime et un autre pour l’enquête : l’ordre chronologique et l’ordre narratif montrent ce que sait le lecteur à chaque instant.',
      s:['Fausse piste', 'Semer et récolter', 'Suspense et surprise', 'Question dramatique', 'Planifier à partir de la fin', 'Style noir (hard-boiled)'] },
    { n:'Fantastique', a:'Fantastique, merveilleux et étrange (Todorov)',
      d:'Récit où le surnaturel ou l’impossible fait irruption dans un monde reconnaissable. Tzvetan Todorov (*Introduction à la littérature fantastique*, 1970) distingue le fantastique (l’hésitation entre explication naturelle et surnaturelle), l’étrange (tout s’explique) et le merveilleux (le surnaturel est accepté sans surprise, comme dans les contes de fées et la fantasy). La Belgique a donné une véritable « école de l’étrange » (Jean Ray, Thomas Owen).',
      u:'Décidez du régime de votre livre : le lecteur doit-il hésiter (fantastique), accepter des règles nouvelles (merveilleux, fantasy) ou recevoir une explication à la fin (étrange) ? Les règles de l’impossible, une fois posées, ne se brisent pas.',
      c:'La magie sans limites tue la tension : si tout est possible, rien n’est en jeu. L’explication finale bâclée défait l’effet fantastique.',
      x:['Jacques Cazotte, *Le Diable amoureux* (1772).', 'Prosper Mérimée, *La Vénus d’Ille* (1837) ; Maupassant, *Le Horla* (1887).', 'Jean Ray, *Malpertuis* (1943).', 'Franz Kafka, *La Métamorphose* (1915) ; Tolkien, *Le Seigneur des anneaux* (1954–1955), fantasy.'],
      s:['Réalisme magique', 'Construction d’univers', 'Vraisemblance', 'Gothique'] },
    { n:'Science-fiction et dystopie', a:'Fiction spéculative · anticipation',
      d:'Récits qui partent d’une hypothèse scientifique, technique ou sociale pour imaginer un autre monde, souvent futur — le français classique disait « roman d’anticipation ». La dystopie imagine une société oppressive qui pousse à l’extrême des tendances du présent ; l’utopie, une société idéale.',
      u:'Partez d’une question « et si… ? » et suivez les conséquences avec rigueur : économie, politique, langue, vie domestique. La meilleure science-fiction parle du présent à travers le futur.',
      c:'L’exposition du monde en blocs (« comme tu le sais, depuis la Grande Guerre… ») est le défaut le plus courant. Montrez le monde à travers les personnages.',
      x:['Cyrano de Bergerac, *L’Autre Monde ou les États et Empires de la Lune* (posthume, 1657).', 'Jules Verne, *Vingt mille lieues sous les mers* (1869–1870) ; René Barjavel, *Ravage* (1943).', 'Pierre Boulle, *La Planète des singes* (1963).', 'George Orwell, *1984* (1949) ; Aldous Huxley, *Le Meilleur des mondes* (1932).'],
      s:['Construction d’univers', 'Exposition distillée', 'Défamiliarisation', 'Prémisse et pitch'] },
    { n:'Roman de mœurs', a:'Peinture d’une société · études de mœurs',
      d:'Roman qui peint les habitudes, les valeurs, les hypocrisies et les conflits d’un milieu social — une ville, une classe, une époque —, souvent avec ironie. Balzac classe une grande partie de *La Comédie humaine* en « Études de mœurs » ; *Madame Bovary* porte en sous-titre « Mœurs de province ».',
      u:'Le milieu est un personnage : fêtes, dîners, conversations de salon, rituels. L’ironie du narrateur révèle l’écart entre ce que disent les personnages et ce qu’ils font.',
      c:'La satire des mœurs vieillit avec elles ; ce qui reste, ce sont les personnages. Ne laissez pas le tableau social engloutir l’histoire.',
      x:['Balzac, *Eugénie Grandet* (1833) et *Le Père Goriot* (1835).', 'Flaubert, *Madame Bovary* (1857) ; Maupassant, *Bel-Ami* (1885).', 'Jane Austen, *Orgueil et Préjugés* (1813).'],
      s:['Satire', 'Style ironique', 'Réalisme et naturalisme', 'Personnage type'] },
    { n:'Roman psychologique', a:'Roman d’analyse · roman d’introspection',
      d:'Roman centré sur la vie intérieure des personnages — motivations, conflits, souvenirs, conscience — plus que sur l’action extérieure. La France en a fait une spécialité, le « roman d’analyse », de *La Princesse de Clèves* à *Adolphe* et à Radiguet.',
      u:'Focalisation proche, monologue intérieur, discours indirect libre, analepses de mémoire. L’action peut être minime ; la tension vient de la contradiction entre ce que le personnage ressent, pense et fait.',
      c:'Sans un conflit concret qui l’oblige à choisir, l’introspection tourne à la rumination. Donnez-lui un événement qui le mette à l’épreuve.',
      x:['Benjamin Constant, *Adolphe* (1816).', 'Raymond Radiguet, *Le Bal du comte d’Orgel* (1924) ; François Mauriac, *Thérèse Desqueyroux* (1927).', 'Dostoïevski, *Crime et Châtiment* (1866).'],
      s:['Monologue intérieur', 'Classicisme', 'Existentialisme', 'Discours indirect libre'] },
    { n:'Roman picaresque', a:'L’antihéros qui vit d’expédients',
      d:'Récit, en général à la première personne, d’un picaro — un marginal rusé qui passe de maître en maître et de lieu en lieu — qui montre la société d’en bas, avec humour et cruauté. Né en Espagne, il a sa grande version française avec le *Gil Blas* de Lesage.',
      u:'Structure épisodique (un maître, une ville, un épisode) et une voix cynique et drôle. Bon pour la satire sociale et les narrateurs peu fiables.',
      c:'Les épisodes détachés ont besoin d’un fil : un changement du narrateur, ou une question qui traverse le livre.',
      x:['*La Vie de Lazarillo de Tormes* (1554), anonyme.', 'Alain-René Lesage, *Histoire de Gil Blas de Santillane* (1715–1735).', 'Cervantès, *Don Quichotte* (1605–1615), qui le parodie et le dépasse ; Céline, *Voyage au bout de la nuit* (1932), picaresque noir.'],
      s:['Antihéros', 'Satire', 'Récit en mosaïque', 'Narrateur non fiable'] },
    { n:'Récit de voyage', a:'Littérature de voyage · roman de la route',
      d:'Récits organisés autour d’un déplacement — réel ou inventé —, où le voyage extérieur accompagne une transformation intérieure. La tradition de langue française va du *Devisement du monde* de Marco Polo (dicté en franco-italien) aux grands voyageurs suisses du XXe siècle.',
      u:'La structure vient de l’itinéraire ; l’intérêt vient du regard. Alternez paysages, rencontres et réflexion. La route ou la mer donnent naturellement un rythme d’épisodes.',
      c:'Le catalogue de lieux ne fait pas un récit : il faut une question et un voyageur qui change.',
      x:['Marco Polo et Rustichello de Pise, *Le Devisement du monde* (vers 1298).', 'Chateaubriand, *Itinéraire de Paris à Jérusalem* (1811).', 'Nicolas Bouvier, *L’Usage du monde* (1963) ; Ella Maillart, *Oasis interdites* (1937).'],
      s:['Voyage du héros', 'Roman d’apprentissage', 'Récit enchâssé'] },
    { n:'Roman de chevalerie', a:'Roman courtois · matière de Bretagne · chanson de geste',
      d:'Récits médiévaux de chevaliers, d’épreuves, d’amour courtois et de merveilleux chrétien. Le genre naît en français : Chrétien de Troyes (vers 1170–1190) invente Lancelot et Perceval, et les grands cycles en prose du XIIIe siècle (*Lancelot-Graal*) fixent la matière arthurienne. La chanson de geste (*La Chanson de Roland*) en est la sœur épique.',
      u:'Source pour la fantasy, le roman historique médiéval et la parodie. La structure de quête (une recherche à épreuves successives) et l’entrelacement des aventures organisent encore beaucoup d’intrigues.',
      c:'Les valeurs du genre (honneur, lignage, chasteté) ne sont pas celles d’aujourd’hui : employez-les en connaissance de cause, ou pour les mettre en question.',
      x:['Chrétien de Troyes, *Lancelot ou le Chevalier de la charrette* et *Perceval ou le Conte du Graal*.', '*La Chanson de Roland* (vers 1100).', '*Amadis de Gaule* (version de Garci Rodríguez de Montalvo, 1508), que lit don Quichotte.'],
      s:['Entrelacement', 'Voyage du héros', 'Fantastique', 'Ancien français'] },
    { n:'Conte et fable', a:'Conte populaire · conte de fées · fable · légende',
      d:'Récits de transmission orale, recueillis et fixés par écrit : contes merveilleux, contes d’animaux, légendes locales, fables à moralité. L’expression « contes de fées » vient de Madame d’Aulnoy (1697), l’année même des *Histoires ou contes du temps passé* de Perrault. Le Québec a une riche tradition de contes populaires (*La Chasse-galerie*).',
      u:'Des structures simples et fortes (trois épreuves, l’interdit transgressé, le cadet qui réussit), des personnages types et un rythme de répétition. À réécrire, à transposer au présent ou à utiliser comme ossature d’un roman.',
      c:'La morale explicite à la fin, dans un récit pour adultes, sonne comme un sermon. Les versions anciennes sont souvent cruelles et étranges — c’est là qu’est leur force (chez Perrault, le Petit Chaperon rouge n’est pas sauvé).',
      x:['Charles Perrault, *Histoires ou contes du temps passé* (1697).', 'Jean de La Fontaine, *Fables* (1668–1694), d’après Ésope et Phèdre.', 'Les frères Grimm, *Contes de l’enfance et du foyer* (1812).', 'Honoré Beaugrand, *La Chasse-galerie* (1891), légende québécoise.'],
      s:['Personnage type', 'Les fonctions de Propp', 'Les sept intrigues fondamentales', 'Allégorie', 'Conte philosophique'] },
    { n:'Conte philosophique', a:'Le conte au service des idées (XVIIIe siècle)',
      d:'Récit bref et rapide, souvent faussement naïf, qui met une idée à l’épreuve à travers les aventures d’un personnage. Voltaire en est le maître : voyages en accéléré, péripéties invraisemblables assumées, ironie constante, conclusion qui laisse le lecteur penser.',
      u:'Excellent modèle pour la fable politique, la satire et la science-fiction d’idées : un regard naïf (un étranger, un enfant, un géant) traverse le monde et en révèle l’absurdité. La vitesse est essentielle — un chapitre, un malheur, une leçon déjouée.',
      c:'Les personnages y sont des fonctions plus que des êtres : la formule ne convient pas à un roman qui veut émouvoir. Et l’idée doit rester une question, pas une réponse.',
      x:['Voltaire, *Zadig* (1747), *Micromégas* (1752), *Candide* (1759), *L’Ingénu* (1767).', 'Antoine de Saint-Exupéry, *Le Petit Prince* (1943), héritier moderne.', 'Swift, *Les Voyages de Gulliver* (1726), son cousin anglais.'],
      s:['Lumières', 'Défamiliarisation', 'Style ironique', 'Conte et fable', 'Allégorie'] },
    { n:'Roman-feuilleton', a:'Roman publié en épisodes dans la presse',
      d:'Roman publié par livraisons dans les journaux, à partir de 1836 (la presse à bas prix d’Émile de Girardin). Il invente une écriture de l’épisode : intrigue foisonnante, personnages hauts en couleur, rebondissements, fin d’épisode à suspense. Il a laissé un adjectif : « rocambolesque », de Rocambole, le héros de Ponson du Terrail.',
      u:'Ses procédés nourrissent aujourd’hui la série télévisée et le roman populaire : faire avancer plusieurs fils à la fois, finir chaque livraison sur une question, ménager des retours de personnages. Utile à quiconque publie en épisodes (en ligne, en saison).',
      c:'Le feuilleton écrit au jour le jour accumule invraisemblances et fils oubliés. Planifiez ce que vous publiez par morceaux.',
      x:['Eugène Sue, *Les Mystères de Paris* (1842–1843).', 'Alexandre Dumas, *Le Comte de Monte-Cristo* (1844–1846).', 'Pierre Alexis Ponson du Terrail, *Rocambole* (à partir de 1857).'],
      s:['Accroche et cliffhanger', 'Chapitres courts et cliffhangers', 'Entrelacement', 'Bible de série'] },
    { n:'Roman du terroir', a:'Roman régionaliste · roman rustique · roman de la terre',
      d:'Roman ancré dans un pays et une vie paysanne, où la terre, le climat et le travail règlent le destin des personnages. Il prend en France la forme du roman champêtre (George Sand), en Suisse romande celle de Ramuz, et au Québec il domine longtemps le roman, avant d’être mis en question par le roman de la ville.',
      u:'Le paysage et les saisons fournissent la structure (semailles, moisson, hiver) ; la langue locale donne la voix. Employez le parler régional par touches, dans le dialogue, et donnez au lieu une force qui pèse sur les choix.',
      c:'La pente idyllique (la bonne terre, les traditions éternelles) a souvent servi une idéologie ; les meilleurs romans du terroir montrent aussi la dureté et le désir de partir.',
      x:['George Sand, *La Mare au diable* (1846).', 'Louis Hémon, *Maria Chapdelaine* (1914), Québec ; Ringuet, *Trente arpents* (1938).', 'Charles Ferdinand Ramuz, *Derborence* (1934), Suisse ; Jean Giono, *Regain* (1930).'],
      s:['Littérature engagée', 'Style lyrique', 'Roman de mœurs', 'Régionalisme'] }
  ]},

  { name:'Manières d’écrire la prose', items:[
    { n:'Style sobre', a:'Prose classique · transparence',
      d:'Prose claire, précise et discrète, qui n’attire pas l’attention sur elle : le lecteur voit l’histoire à travers elle, comme à travers une vitre propre.',
      u:'Des phrases bien construites, un vocabulaire exact, des adjectifs choisis un à un, des métaphores rares et justes. C’est le registre le plus polyvalent et celui qui vieillit le mieux. Stendhal disait lire le Code civil pour prendre le ton juste ; Colette conseillait à Simenon de couper toute « littérature ».',
      c:'Sobre ne veut dire ni pauvre ni neutre : la précision demande du travail. Sans aucune image forte, le texte devient gris.',
      x:['Stendhal, *La Chartreuse de Parme* (1839).', 'Georges Simenon, *La neige était sale* (1948).', 'J. M. Coetzee, *Disgrâce* (1999).'],
      s:['Minimalisme', 'Style lyrique', 'Classicisme', 'Choix lexical'] },
    { n:'Style lyrique', a:'Prose poétique dans le récit',
      d:'Prose qui se rapproche de la poésie : rythme marqué, images, répétitions, musicalité, attention aux sensations et aux états d’âme.',
      u:'Bon pour la mémoire, le paysage, l’enfance, la perte, et pour les narrateurs sensibles au monde. Alternez avec des passages plus sobres, pour que le lyrisme garde son effet.',
      c:'Un roman entièrement lyrique fatigue et peut étouffer l’action. L’émotion doit naître des images, non des adjectifs.',
      x:['Colette, *Sido* (1930).', 'Jean Giono, *Que ma joie demeure* (1935).', 'Alain-Fournier, *Le Grand Meaulnes* (1913).'],
      s:['Prose poétique', 'Symbolisme et décadentisme', 'Roman du terroir', 'Rythme de la phrase'] },
    { n:'Style télégraphique', a:'Phrases nominales · ellipses',
      d:'Prose faite de phrases très courtes, souvent sans verbe, avec ellipse des articles et des liaisons. Elle imite la prise de notes, l’urgence, la pensée en éclairs.',
      u:'Utile dans les scènes de tension extrême, les journaux intimes, les carnets d’un personnage, la pensée de quelqu’un sous le choc. À petites doses, elle donne de la vitesse.',
      c:'Sur des pages entières, elle fatigue et ressemble à un scénario ou à une liste. Employez-la comme changement de rythme.',
      x:['« Sirène. Fumée. Personne dans l’escalier. Le téléphone, encore. »', 'Carnet d’un personnage : « Lundi. Pluie. Lettre de M. Pas ouverte. »'],
      s:['Style cinématographique', 'Phrase nominale', 'Phrase courte', 'Asyndète'] },
    { n:'Style cinématographique', a:'Écrire par plans',
      d:'Prose qui imite la caméra : elle décrit ce qui se voit et s’entend, par plans (plan d’ensemble, plan moyen, gros plan), avec des coupes franches entre les scènes, peu de commentaires et souvent au présent.',
      u:'Très efficace en action et en suspense. Pensez en plans : ouvrez large, approchez-vous du détail révélateur, coupez. L’outil, avec les Scènes sur le Récit, aide à monter le livre comme sur une table de montage.',
      c:'Un livre n’est pas un film : la prose peut entrer dans la tête des personnages, ce que la caméra ne fait pas. Y renoncer, c’est gaspiller ce que seul le roman possède.',
      x:['Ouverture par plans : « La plage vide. Une serviette rouge. À côté, une chaussure d’enfant. »', 'Alain Robbe-Grillet, *La Jalousie* (1957) ; Marguerite Duras, *Le Ravissement de Lol V. Stein* (1964).'],
      t:'Pensez chaque Scène comme une séquence : un lieu, un temps, un plan d’ouverture et un plan de sortie ; le Récit sert alors de table de montage.',
      s:['Montage alterné', 'Montrer plutôt que dire', 'Entrer tard, sortir tôt', 'Nouveau Roman', 'Troisième personne objective (caméra)'] },
    { n:'Style de reportage', a:'Journalisme littéraire · récit de non-fiction',
      d:'Prose qui emploie les techniques du roman pour raconter des faits réels, ou fiction qui imite le reportage (dates, noms, documents, témoignages). Truman Capote, *De sang-froid* (1966), et le « nouveau journalisme » américain en sont les références ; en France, la tradition du grand reportage (Albert Londres) et le « roman vrai » d’Emmanuel Carrère.',
      u:'Il donne vraisemblance et urgence. Dans la fiction, le faux reportage (entretiens, transcriptions, articles de presse) crée des effets de documentaire.',
      c:'Dans la non-fiction, inventer, c’est rompre le pacte avec le lecteur. Dans la fiction, le faux reportage exige une cohérence totale des détails.',
      x:['Truman Capote, *De sang-froid* (1966).', 'Emmanuel Carrère, *L’Adversaire* (2000).', 'Svetlana Alexievitch, *La guerre n’a pas un visage de femme* (1985).'],
      s:['Vraisemblance', 'Autofiction', 'Détail révélateur'] },
    { n:'Style essayistique', a:'Le roman qui pense',
      d:'Récit où le narrateur (ou l’auteur) interrompt l’histoire pour réfléchir — sur la vie, la société, l’écriture elle-même —, rapprochant le roman de l’essai. Montaigne en est l’ancêtre lointain, Proust le grand exemple français.',
      u:'Cela fonctionne quand la réflexion naît de l’histoire et l’éclaire. Un narrateur qui pense à voix haute peut devenir le grand personnage du livre.',
      c:'Les digressions freinent l’intrigue : dosez-les, et assurez-vous que chacune apporte ce que la scène ne dirait pas.',
      x:['Marcel Proust, *Le Temps retrouvé* (1927).', 'Milan Kundera, *L’Insoutenable Légèreté de l’être* (1984).', 'Robert Musil, *L’Homme sans qualités* (1930–1943).'],
      s:['Pause descriptive', 'Existentialisme', 'Métafiction', 'Narrateur intrusif (commentateur)'] },
    { n:'Style ironique', a:'Distance et double sens',
      d:'Prose où le narrateur dit une chose et en laisse entendre une autre : l’éloge qui est une critique, le sérieux qui est une moquerie. L’ironie crée une complicité avec le lecteur.',
      u:'L’ironie vit de l’écart entre le ton et le contenu, entre ce que le personnage pense de lui-même et ce que voit le lecteur. Voltaire, Stendhal et Flaubert en sont des maîtres en français.',
      c:'Une ironie constante vide les personnages et empêche le lecteur de tenir à eux. Sachez quand la mettre de côté.',
      x:['Voltaire, *Candide* (1759).', 'Flaubert, *Bouvard et Pécuchet* (posthume, 1881).', 'Machado de Assis, *Mémoires posthumes de Brás Cubas* (1881) ; Jane Austen, *Emma* (1815).'],
      s:['Ironie', 'Satire', 'Roman de mœurs', 'Conte philosophique', 'Narrateur intrusif (commentateur)'] }
  ]}
  ]});
